/* Généré depuis le guidebook de la maquette. Le contenu reste hors de la limite du champ HTML. */
(function () {
  var mount = document.getElementById("lgdc-guidebook-mount");
  if (!mount) return;
  var fragment = document.createElement("template");
  fragment.innerHTML = "<main class=\"lgdc lgdc-forum\" id=\"lgdc-forum\">\n\n<header class=\"lgdc-forum-head lgdc-mbs__head\">\n  <div>\n    <nav class=\"lgdc-micro lgdc-crumbs\" aria-label=\"Fil d’Ariane\"><a href=\"/\">Index</a></nav>\n    <h1>Guidebook</h1>\n  </div>\n</header>\n\n<div class=\"lgdc-gb\">\n  <input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-bases\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-reglement\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-clans\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-code\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-noms\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-systeme\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-remedes\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-glossaire\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-credits\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n  <aside class=\"lgdc-gb__side\" aria-label=\"Chapitres du guidebook\">\n    <ul class=\"lgdc-gb__chapters\"><li><label for=\"lgdc-gb-bases\">Les bases</label></li><li><label for=\"lgdc-gb-reglement\">Règlement</label></li><li><label for=\"lgdc-gb-clans\">Les Clans</label></li><li><label for=\"lgdc-gb-code\">Le code des guerriers</label></li><li><label for=\"lgdc-gb-noms\">Les noms</label></li><li><label for=\"lgdc-gb-systeme\">Le système</label></li><li><label for=\"lgdc-gb-remedes\">Les remèdes</label></li><li><label for=\"lgdc-gb-glossaire\">Glossaire</label></li><li><label for=\"lgdc-gb-credits\">Crédits</label></li></ul>\n  </aside>\n\n  <article class=\"lgdc-frame lgdc-gb__page\">\n    <div class=\"lgdc-frame__in\">\n      <div class=\"lgdc-gb__panel\" data-tab=\"bases\">\n        <section id=\"debuter\">\n          <h2>Débuter</h2>\n          <p>Wildheart est un forum RPG inspiré de <i>La Guerre des Clans</i>, la saga d’Erin Hunter. On y joue des chats sauvages qui vivent en Clans dans la forêt : chaque Clan a son territoire, son chef, ses guerriers et ses croyances. Pas besoin d’avoir lu les livres, tout ce qu’il faut savoir se trouve dans ce guidebook.</p>\n          <h3 class=\"lgdc-gb__sub\">Les notions à connaître</h3>\n          <dl class=\"lgdc-gbs__facts\">\n            <div><dt>Les Clans</dt><dd>Quatre groupes de chats rivaux qui se partagent la forêt, chacun sur son territoire. Voir <a href=\"#quatre\">Les Clans</a>.</dd></div>\n            <div><dt>Les rangs</dt><dd>Un chat naît chaton, devient apprenti à six lunes auprès d’un mentor, puis guerrier. Le lieutenant seconde le chef ; le guérisseur soigne le Clan ; les reines élèvent les petits et les anciens se reposent. Voir <a href=\"#gl-rangs\">les rangs</a>.</dd></div>\n            <div><dt>Le Clan des Étoiles</dt><dd>Les ancêtres morts, qui veillent sur les Clans depuis le ciel. Les guérisseurs lisent leurs signes, et le chef reçoit d’eux ses neuf vies.</dd></div>\n            <div><dt>L’Assemblée</dt><dd>À chaque pleine lune, les quatre Clans se retrouvent en trêve autour du grand rocher, au centre de la réserve. Voir <a href=\"#carte\">la carte</a>.</dd></div>\n            <div><dt>Le code du guerrier</dt><dd>Les lois que tous les Clans respectent. Voir <a href=\"#code-texte\">le code</a>.</dd></div>\n            <div><dt>Les lunes</dt><dd>Le temps se compte en lunes. Sur le forum, une lune va d’une pleine lune réelle à la suivante, soit environ un mois. Voir <a href=\"#temps\">Le temps qui passe</a>.</dd></div>\n          </dl>\n          <h3 class=\"lgdc-gb__sub\">Les étapes</h3>\n          <ol class=\"lgdc-gb__steps\">\n            <li>Lis <a href=\"#foret\">Les bases</a> et le <a href=\"#inscription\">règlement</a>.</li>\n            <li>Choisis un Clan qui a encore des places, puis le rang de ton personnage. Voir <a href=\"#quatre\">Les Clans</a>.</li>\n            <li>Choisis son nom en suivant <a href=\"#noms-regles\">les règles des noms</a>. Le <a href=\"#noms-generateur\">générateur</a> peut t’inspirer, mais il n’est pas obligatoire.</li>\n            <li>Crée ton compte au nom du personnage et poste sa fiche dans le <a href=\"/f7-presentations\">forum des présentations</a>. En ouvrant un nouveau sujet, le formulaire de présentation s’affiche tout seul : il suffit de le remplir, la fiche se met en page automatiquement. Un <a href=\"#predefinis\">prédéfini</a> attend peut-être son joueur.</li>\n            <li>Une fois la fiche validée par le staff, poste ta <a href=\"/f2-fiche-de-liens\">fiche de liens</a> et lance ton premier RP. Dans l’éditeur, la boîte <b>Mise en page</b> propose quatre modèles de RP : bannière, colonne, bandeau ou encadré.</li>\n          </ol>\n          <h3 class=\"lgdc-gb__sub\">Et le système ?</h3>\n          <p>Pas besoin de le maîtriser pour commencer : sur Wildheart, on écrit d’abord. Les dés ne sont obligatoires que pour la chasse, les portées et les intrigues, et l’éditeur fait les calculs. <a href=\"#sys\">Le système</a> se lit le jour où tu en as besoin, et <a href=\"#remedes\">les remèdes</a> ne concernent que les guérisseurs. Une question ? Le staff répond sur le forum ou sur le Discord.</p>\n\n        </section>\n\n        <section id=\"foret\">\n          <h2>La forêt</h2>\n          <p>Wildheart se déroule en 2026, dans la réserve intégrale d’Arc-Châteauvillain, au cœur du Parc national de forêts, entre la Champagne et la Bourgogne. Sur un peu plus de 3 000 hectares, on ne coupe plus d’arbres et la forêt évolue seule. Les humains y sont rares : on n’y entre que sur autorisation, à part sur un sentier.</p>\n          <p>Pour le jeu, la réserve a été beaucoup modifiée, notamment ses milieux : rochers, futaie, prairies et marais y sont plus variés et plus marqués que dans la vraie forêt, pour offrir un terrain plus riche et plus amusant à jouer. Ne cherche pas à tout retrouver sur une carte réelle.</p>\n          <p>Quatre Clans de chats sauvages s’y partagent le territoire. Chacun a ses frontières, ses lieux et ses règles. La paix entre eux est toute neuve, et fragile.</p>\n          <p>Au sud, le Clan du Crépuscule vit sur les affleurements calcaires et les éboulis du rebord du plateau. Au nord, le Clan du Hêtre tient la futaie de hêtres, le plus grand territoire avec celui du Crépuscule. À l’est, le Clan de l’Orchidée occupe les clairières et les pelouses de la lisière, contre les champs : le plus petit territoire, mais le plus ouvert. À l’ouest, le Clan du Brouillard tient le fond des vallons, où les sources forment des marais. Les quatre se touchent en un seul point, la clairière de l’Assemblée, au confluent des ruisseaux.</p>\n          <p>Autour de la réserve, le reste du parc est ouvert aux promeneurs, aux chasseurs et aux bûcherons. Plus loin, les villages, les fermes, les routes et les terres que personne ne revendique appartiennent aux solitaires, aux chats errants et aux chats domestiques. Les Clans les croisent, les chassent ou les recrutent.</p>\n        </section>\n\n        <section id=\"carte\">\n          <h2>La carte</h2>\n          <p>La réserve vue d’en haut. Survole les repères pour voir les lieux que tout chat de Clan connaît.</p>\n          <figure class=\"lgdc-map\" aria-label=\"Carte de la réserve\">\n            <div class=\"lgdc-map__img\">\n              <span class=\"lgdc-map__clan\" style=\"--x:70%;--y:73%;--g1:#8e7f9a;--sym:var(--sym-clan-crepuscule)\"><i aria-hidden=\"true\"></i>Clan du Crépuscule</span>\n              <span class=\"lgdc-map__clan\" style=\"--x:62%;--y:16%;--g1:#b07a4f;--sym:var(--sym-clan-hetre)\"><i aria-hidden=\"true\"></i>Clan du Hêtre</span>\n              <span class=\"lgdc-map__clan\" style=\"--x:77%;--y:40%;--g1:#c2a24f;--sym:var(--sym-clan-orchidee)\"><i aria-hidden=\"true\"></i>Clan de l’Orchidée</span>\n              <span class=\"lgdc-map__clan\" style=\"--x:17%;--y:31%;--g1:#8a99a4;--sym:var(--sym-clan-brouillard)\"><i aria-hidden=\"true\"></i>Clan du Brouillard</span>\n              <span class=\"lgdc-map__place\" style=\"--x:55.7%;--y:56%\">Assemblée</span>\n              <button type=\"button\" class=\"lgdc-map__pin\" style=\"--x:55.7%;--y:48%\" aria-label=\"Le grand rocher\"><i class=\"ph-light ph-users-three\" aria-hidden=\"true\"></i><span class=\"lgdc-map__tip\"><b>Le grand rocher</b>Là où les chefs parlent, à chaque pleine lune.</span></button>\n              <button type=\"button\" class=\"lgdc-map__pin\" style=\"--x:43.5%;--y:27%\" aria-label=\"La source du Hêtre\"><i class=\"ph-light ph-drop\" aria-hidden=\"true\"></i><span class=\"lgdc-map__tip\"><b>La source du Hêtre</b>Elle naît sous les hêtres et descend jusqu’à l’Assemblée.</span></button>\n              <button type=\"button\" class=\"lgdc-map__pin\" style=\"--x:22%;--y:47%\" aria-label=\"Les marais\"><i class=\"ph-light ph-waves\" aria-hidden=\"true\"></i><span class=\"lgdc-map__tip\"><b>Les marais</b>Le fond du vallon, entre roseaux et eau dormante.</span></button>\n              <button type=\"button\" class=\"lgdc-map__pin lgdc-map__pin--right\" style=\"--x:86%;--y:83%\" aria-label=\"La grotte\"><i class=\"ph-light ph-mountains\" aria-hidden=\"true\"></i><span class=\"lgdc-map__tip\"><b>La grotte</b>Une entrée sombre au pied des falaises du plateau.</span></button>\n              <button type=\"button\" class=\"lgdc-map__pin lgdc-map__pin--left\" style=\"--x:4.5%;--y:61%\" aria-label=\"La maison forestière\"><i class=\"ph-light ph-house\" aria-hidden=\"true\"></i><span class=\"lgdc-map__tip\"><b>La maison forestière</b>Des humains y vivent, juste hors de la réserve.</span></button>\n              <button type=\"button\" class=\"lgdc-map__pin lgdc-map__pin--right\" style=\"--x:90.5%;--y:54%\" aria-label=\"La ferme\"><i class=\"ph-light ph-house\" aria-hidden=\"true\"></i><span class=\"lgdc-map__tip\"><b>La ferme</b>Au bout du chemin, contre les champs de l’est.</span></button>\n            </div>\n            <figcaption class=\"lgdc-micro\">Les champs et les maisons sont hors de la réserve, en territoire de solitaires.</figcaption>\n          </figure>\n        </section>\n\n        <section id=\"paix\">\n          <h2>Une paix nouvelle</h2>\n          <div class=\"lgdc-gb__prologue\">\n          <p>La pleine lune s’était levée sur l’Assemblée, et pour la première fois depuis cent lunes, personne n’avait sorti les griffes. Au pied du grand rocher, une jeune guerrière du Clan du Brouillard huma l’air froid, chargé de l’odeur des quatre Clans. Là-haut, les chefs venaient de poser la patte sur la même pierre. Pas un feulement. Rien que le vent dans les herbes.</p>\n          <p>Une paix&nbsp;? La guerrière plaqua les oreilles. Elle était née pendant la guerre, comme tous ceux de son âge. Les anciens, eux, se souvenaient du début&nbsp;: une saison des feuilles vertes sans pluie, il y a cent lunes, quand les sources du vallon avaient tari et que le gibier avait fui la futaie. Une patrouille du Hêtre avait traversé la clairière de l’Assemblée pour chasser sur les rochers du Crépuscule, et nourrir ses petits. Une autre, du Crépuscule, l’avait chassée à coups de griffes. Le sang avait appelé le sang.</p>\n          <p>Depuis, les frontières n’avaient jamais cessé de bouger. Le Crépuscule descendait de ses rochers à chaque mauvaise saison. L’Orchidée défendait ses clairières contre tous. Le Brouillard tendait des embuscades dans les roseaux, et le Hêtre, pris entre les marais et les prairies, se battait sur deux flancs à la fois. Aux Assemblées, la trêve tenait à peine jusqu’au coucher de la lune. Les patrouilles partaient à l’aube&nbsp;; certaines ne revenaient pas.</p>\n          <p>Puis vint la mauvaise saison la plus dure que la forêt ait connue. La glace prit les ruisseaux, le froid prit les anciens et les petits, dans chaque camp. Ce furent les guérisseurs qui firent le premier pas&nbsp;: tous les huit, ils se retrouvèrent en secret, loin des frontières, pour partager les herbes qui leur restaient. Quand ils revinrent, ils portaient le même message à leur chef. Le Clan des Étoiles en avait assez de recevoir des guerriers morts trop jeunes.</p>\n          <p>Il fallut trois Assemblées pour que les chefs acceptent de s’écouter. Cette nuit, enfin, ils avaient juré. Pour marquer la fin de la guerre, ils avaient décidé de recommencer le compte des lunes&nbsp;: la paix ouvrait une nouvelle ère.</p>\n          <p>La guerrière ne quittait pas la clairière des yeux. En face, un matou du Crépuscule la fixait sans ciller. Elle connaissait cette odeur. Elle l’avait sentie sur la frontière, la nuit où son frère n’était pas rentré. Combien de temps avant que quelqu’un brise ce silence&nbsp;?</p>\n          </div>\n        </section>\n\n        <section id=\"temps\">\n          <h2>Le temps qui passe</h2>\n          <p>Les chats comptent en lunes. Sur le forum, <b>une lune va d’une pleine lune à la suivante</b>, comme dans le ciel réel : une nouvelle lune se lève le lendemain de chaque pleine lune, et l’Assemblée tombe le dernier jour de la lune. Le compte a repris à zéro avec <a href=\"#paix\">la paix</a> : un chat plus âgé qu’elle est né pendant la guerre, ou avant pour les plus vieux anciens, et s’en souvient. Les âges, les apprentissages et les saisons suivent ce calendrier.</p>\n          <p>À chaque pleine lune, les quatre Clans se retrouvent au lieu de l’Assemblée. La trêve y est obligatoire : on y échange des nouvelles, pas des coups.</p>\n          <h3 class=\"lgdc-gb__sub\">Les âges</h3>\n          <p>Ce sont des chats sauvages : ils vivent moins longtemps qu’un chat domestique. L’équivalent humain donne une idée de leur maturité.</p>\n          <div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs\"><thead><tr><th scope=\"col\">Lunes</th><th scope=\"col\">Âge réel</th><th scope=\"col\">Équivalent humain</th><th scope=\"col\">Rang et étape</th></tr></thead><tbody><tr><td>0 à 1</td><td>moins d’un mois</td><td>0 à 2 ans</td><td><b>Chaton</b> nouveau-né, ne quitte pas la pouponnière</td></tr><tr><td>1 à 3</td><td>1 à 3 mois</td><td>3 à 7 ans</td><td><b>Chaton</b>, premiers pas dans le camp sous surveillance</td></tr><tr><td>3 à 6</td><td>3 à 6 mois</td><td>7 à 12 ans</td><td><b>Chaton</b>, se promène dans le camp, jamais seul dehors</td></tr><tr><td>6</td><td>6 mois</td><td>12 ans</td><td>Devient <b>apprenti</b></td></tr><tr><td>6 à 12</td><td>6 mois à 1 an</td><td>12 à 17 ans</td><td><b>Apprenti</b></td></tr><tr><td>12</td><td>1 an</td><td>18 ans</td><td>Peut devenir <b>guerrier</b>, et avoir des petits une fois l’apprentissage fini</td></tr><tr><td>24</td><td>2 ans</td><td>25 ans</td><td><b>Guerrier</b> dans la force de l’âge, peut devenir lieutenant</td></tr><tr><td>36</td><td>3 ans</td><td>32 ans</td><td><b>Guerrier</b> expérimenté, peut être chef dès 30 lunes</td></tr><tr><td>48</td><td>4 ans</td><td>38 ans</td><td><b>Guerrier</b>, souvent mentor ou lieutenant</td></tr><tr><td>60</td><td>5 ans</td><td>44 ans</td><td><b>Guerrier</b> confirmé</td></tr><tr><td>72</td><td>6 ans</td><td>50 ans</td><td><b>Guerrier âgé</b>, qui commence à ralentir</td></tr><tr><td>85</td><td>7 ans</td><td>55 ans</td><td>Peut devenir <b>ancien</b></td></tr><tr><td>100</td><td>8 ans</td><td>60 ans</td><td>La plupart des chats sont <b>anciens</b></td></tr><tr><td>115</td><td>9 ans et demi</td><td>68 ans</td><td><b>Ancien</b> âgé</td></tr><tr><td>130 et plus</td><td>10 ans et plus</td><td>75 ans et plus</td><td><b>Ancien</b> très âgé, rare dans la nature</td></tr></tbody></table></div>\n          <p>Un chat peut devenir ancien à partir de 85 lunes, comme dans les livres, où un guerrier rejoint les anciens vers 6 ou 7 ans. Plus tôt, seule une blessure ou une maladie qui l’empêche de chasser et de se battre le permet. Ce n’est jamais obligatoire, et le chef et le guérisseur peuvent garder leur rôle au-delà.</p>\n          \n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"reglement\">\n        <section id=\"inscription\">\n          <h2>L’inscription</h2>\n        <p>Il faut avoir <b>15 ans ou plus</b> pour s’inscrire. Wildheart s’adresse surtout aux adultes qui ont grandi avec les livres, mais les plus jeunes y sont les bienvenus, et le staff veille à les protéger.</p>\n        <p>Les RP peuvent aborder des sujets durs : fais attention à ce que tu lis, à ce que tu partages de toi, et prends soin de toi. Si quelque chose te met mal à l’aise, parles-en au staff.</p>\n        <p>Lis le guidebook en entier avant de poster ta fiche : on part du principe que tu le connais.</p>\n        <p>Ton compte porte le nom de ton personnage. Ton pseudo de joueur ou de joueuse se renseigne dans le profil.</p>\n        <p>Après l’inscription, tu as <b>une semaine</b> pour poster une ébauche de présentation, puis <b>dix jours</b> de plus pour la terminer. Ces délais se prolongent sur simple demande au staff.</p>\n        <p>Chaque Clan ouvre un nombre limité de places aux joueurs : un Clan plein est fermé (voir <a href=\"#quatre\">Les quatre Clans</a>).</p>\n        </section>\n\n        <section id=\"activite\">\n          <h2>L’activité</h2>\n        <p>On demande <b>au moins un message RP par lune</b> (environ un mois réel) pour chaque personnage. Un message dans un sujet en cours suffit.</p>\n        <p>Au début de chaque lune, le staff ouvre un <b>recensement</b> : chaque personnage y confirme sa présence. Un personnage sans message RP pendant une lune et absent du recensement passe aux archives. Il peut revenir à tout moment sur simple demande.</p>\n        <p>Une absence de plus d’une semaine se signale dans le forum des <a href=\"/f18-absences\">absences</a>. Un personnage dont l’absence est signalée n’est pas archivé.</p>\n        </section>\n\n        <section id=\"comptes\">\n          <h2>Les multicomptes</h2>\n        <p>Tu peux jouer plusieurs personnages, un par compte. Un nouveau compte peut s’ouvrir <b>un mois après la validation</b> de ton dernier personnage.</p>\n        </section>\n\n        <section id=\"avatars\">\n          <h2>Les avatars</h2>\n        <p>Ton avatar peut être <b>un dessin de chat</b>, y compris réalisé sur Picrew ou un outil similaire, <b>une photo réelle de chat</b>, <b>une illustration d’un personnage de la saga officielle <i>La Guerre des Clans</i></b> ou <b>une capture d’écran du jeu WCUE sur Roblox</b>. Pour un dessin, indique simplement le nom de l’artiste dans le profil, sans lien. Les images créées par intelligence artificielle sont interdites.</p>\n        <p>Un avatar est <b>carré</b>, et fait au moins 250 × 250 pixels. Une image d’un autre format sera recadrée.</p>\n        </section>\n\n        <section id=\"vraisemblance\">\n          <h2>La vraisemblance</h2>\n        <p>Wildheart tient à la vraisemblance : tes personnages sont des chats sauvages, avec leurs limites. Un chaton ne quitte pas le camp seul, ne chasse pas et ne se bat pas contre un adulte. Aucun personnage ne gagne tous ses combats, ne devine les intentions des autres ou n’impose sa loi à toute la forêt.</p>\n        <p>Ce que tu sais en tant que joueur ou joueuse, ton personnage ne le sait pas forcément.</p>\n        </section>\n\n        <section id=\"couples\">\n          <h2>Les relations et les portées</h2>\n        <p>Les relations amoureuses sont interdites entre membres d’une même famille, cousins compris, et entre un mentor et son apprenti, même une fois l’apprentissage terminé. Contrairement aux livres, les guérisseurs peuvent avoir un ou une partenaire. Chaque Clan a deux guérisseurs : si ce sont deux chattes, une seule peut être reine à la fois, pour que l’autre continue de soigner le Clan.</p>\n        <p>Une portée se tente aux dés, et le nombre de chatons aussi : voir <a href=\"#sys-temps\">Les portées</a>.</p>\n        </section>\n\n        <section id=\"contenu\">\n          <h2>Ce qu’on peut écrire</h2>\n        <p>Les combats, les blessures et les morts font partie de la vie des Clans. Un message qui contient une scène violente ou difficile commence par la balise <code>&lt;tw&gt;…&lt;/tw&gt;</code>, avec la liste de ce qu’il contient. Par exemple, <code>&lt;tw&gt;sang, mort d’un personnage&lt;/tw&gt;</code> s’affiche ainsi :</p>\n        <tw>sang, mort d’un personnage</tw>\n        <p>Pas de contenu sexuel, ni explicite ni suggéré. Pas de contenu discriminatoire, en RP comme hors RP.</p>\n        <p>Par souci de cohérence visuelle, seules les mises en page du forum sont autorisées : les formulaires de présentation, de liens et de chronologie, et les modèles de la boîte <b>Mise en page</b> de l’éditeur. Les fiches et les codes créés ailleurs sont interdits.</p>\n        </section>\n\n        <section id=\"predefinis\">\n          <h2>Les prédéfinis</h2>\n        <p>Les prédéfinis ne se réservent pas : le premier ou la première à poster sa fiche le prend.</p>\n        </section>\n\n        <section id=\"respect\">\n          <h2>Entre membres</h2>\n        <p>On ne contrôle pas le personnage de quelqu’un d’autre sans son accord : pas de coup qui touche à coup sûr, pas de réaction écrite à sa place. Les conflits entre personnages restent en RP.</p>\n        <p>Le plagiat entraîne la suppression du sujet concerné. Pour toute question ou tout problème, écris au staff sur le forum ou sur le Discord : il ne répond pas en message privé.</p>\n        <p>Les mêmes règles s’appliquent sur le Discord du forum.</p>\n        </section>\n\n        <section id=\"sanctions\">\n          <h2>Sanctions et évolutions</h2>\n        <p>Les sanctions sont laissées à l’appréciation du staff, selon la gravité des faits. Ce règlement peut évoluer : les changements sont annoncés dans le forum des annonces.</p>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"clans\">\n        <section id=\"relations\">\n          <h2>Les relations</h2>\n          <figure class=\"lgdc-gbm\">\n            <div class=\"lgdc-gbm__map\" role=\"img\" aria-label=\"Clan du Crépuscule et Clan du Brouillard : alliés. Clan du Crépuscule et Clan du Hêtre : neutres. Clan du Crépuscule et Clan de l’Orchidée : ennemis. Clan du Hêtre et Clan de l’Orchidée : alliés. Clan du Hêtre et Clan du Brouillard : ennemis. Clan de l’Orchidée et Clan du Brouillard : neutres.\">\n              <svg viewBox=\"0 0 600 340\" aria-hidden=\"true\"><line class=\"lgdc-gbm__l lgdc-gbm__l--aime\" x1=\"110\" y1=\"70\" x2=\"490\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--neutre\" x1=\"110\" y1=\"70\" x2=\"490\" y2=\"70\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--deteste\" x1=\"110\" y1=\"70\" x2=\"110\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--aime\" x1=\"490\" y1=\"70\" x2=\"110\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--deteste\" x1=\"490\" y1=\"70\" x2=\"490\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--neutre\" x1=\"110\" y1=\"270\" x2=\"490\" y2=\"270\"/></svg>\n              <ul aria-hidden=\"true\"><li style=\"--g1:#8e7f9a;--g2:#b59ab8;left:18.333333333333332%;top:20.58823529411765%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-crepuscule)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Crépuscule</span></li><li style=\"--g1:#b07a4f;--g2:#c99566;left:81.66666666666667%;top:20.58823529411765%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-hetre)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Hêtre</span></li><li style=\"--g1:#c2a24f;--g2:#d1b46a;left:18.333333333333332%;top:79.41176470588235%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-orchidee)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Orchidée</span></li><li style=\"--g1:#8a99a4;--g2:#7fa39a;left:81.66666666666667%;top:79.41176470588235%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-brouillard)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Brouillard</span></li></ul>\n            </div>\n            <figcaption class=\"lgdc-gbm__legend\"><span class=\"lgdc-gbm__k lgdc-gbm__k--aime\">Alliés</span><span class=\"lgdc-gbm__k lgdc-gbm__k--neutre\">Neutres</span><span class=\"lgdc-gbm__k lgdc-gbm__k--deteste\">Ennemis</span></figcaption>\n          </figure>\n        </section>\n\n        <section id=\"quatre\">\n          <h2>Les quatre Clans</h2>\n          <p>Chaque Clan compte bien plus de chats que de personnages joués : la plupart de ses membres sont des PNJ. Pour garder les Clans équilibrés, chacun ouvre pour l’instant <b>vingt-huit places</b> aux joueurs. Ce nombre augmentera quand les quatre Clans seront bien remplis, sans compter les portées à venir.</p>\n          <p>Comme au début des livres, chaque Clan liste ses membres joués, rôle par rôle. Les places se répartissent de la même façon dans les quatre Clans. Un rôle complet est fermé, sauf pour les chatons d’une portée dont au moins un parent est joué.</p>\n          <p>Les traits de chaque Clan décrivent sa culture, pas le caractère obligatoire de chacun de ses membres.</p>\n          <div class=\"lgdc-gbc\">\n            <input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-crepuscule\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-hetre\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-orchidee\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-brouillard\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n            <div class=\"lgdc-gbc__tabs\"><label for=\"lgdc-gbc-crepuscule\" style=\"--g1:#8e7f9a\">Crépuscule</label><label for=\"lgdc-gbc-hetre\" style=\"--g1:#b07a4f\">Hêtre</label><label for=\"lgdc-gbc-orchidee\" style=\"--g1:#c2a24f\">Orchidée</label><label for=\"lgdc-gbc-brouillard\" style=\"--g1:#8a99a4\">Brouillard</label></div>\n            <div class=\"lgdc-gbc__panels\">\n              <div class=\"lgdc-gbc__panel\" data-clan=\"crepuscule\" style=\"--g1:#8e7f9a;--g2:#b59ab8\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#8e7f9a;--g2:#b59ab8\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-crepuscule)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan du Crépuscule</h3><p class=\"lgdc-gbc__traits\">Disciplinés, vigilants, endurants, froids &amp; inflexibles.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>Les rochers du plateau</dd></div>\n                  <div><dt>Places libres</dt><dd data-lgdc-libres=\"28\">28 / 28</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Lézards des murailles, campagnols et lérots débusqués entre les pierres, oiseaux qui nichent dans les falaises. Les lapins se chassent sur le plateau, au bord des rochers.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Des guetteurs se relaient jour et nuit sur les hauteurs, d’où l’on voit venir n’importe quelle patrouille. Les apprentis apprennent à se battre en groupe avant d’apprendre à se battre seuls.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Un nouveau guerrier passe sa veillée seul, sur le plus haut rocher du territoire, face au vent. S’il descend avant l’aube, il recommence la nuit suivante.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Hêtre</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>La guerre a commencé quand une de leurs patrouilles a traversé l’Assemblée pour chasser sur les rochers du Crépuscule. Le Clan ne l’a pas oublié, mais il respecte leur sagesse et préfère les tenir à distance.</dd></div><div><dt>Clan de l’Orchidée</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>À chaque mauvaise saison, quand le Crépuscule descendait chasser dans les prairies, l’Orchidée l’attendait. Des têtes brûlées sans discipline, à qui le Crépuscule reproche ses morts.</dd></div><div><dt>Clan du Brouillard</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Pendant la guerre, leurs patrouilles et celles du Crépuscule se croisaient souvent sans un coup de griffe. Le Crépuscule se méfie de leurs ruses, mais respecte un Clan qui sait attendre.</dd></div><div><dt>Solitaires</dt><dd>Reconduits à la frontière. Pendant la guerre, le Clan a recruté ceux qui acceptaient d’obéir, et la paix n’y a rien changé.</dd></div><div><dt>Chats domestiques</dt><dd>Des chats de ferme rôdent parfois au pied des rochers. Le Crépuscule les méprise : ils ont vendu leur liberté contre un toit.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div data-role=\"Chef\" data-n=\"1\"><dt>Chef</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Lieutenant\" data-n=\"1\"><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guérisseur\" data-n=\"2\"><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprenti guérisseur\" data-n=\"2\"><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guerriers\" data-n=\"8\"><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprentis\" data-n=\"5\"><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Reines\" data-n=\"2\"><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Chatons\" data-n=\"4\"><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Anciens\" data-n=\"3\"><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n              <div class=\"lgdc-gbc__panel\" data-clan=\"hetre\" style=\"--g1:#b07a4f;--g2:#c99566\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#b07a4f;--g2:#c99566\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-hetre)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan du Hêtre</h3><p class=\"lgdc-gbc__traits\">Sages, pieux, hospitaliers, bornés &amp; rancuniers.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>La futaie de hêtres</dd></div>\n                  <div><dt>Places libres</dt><dd data-lgdc-libres=\"28\">28 / 28</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Écureuils, mulots, loirs, merles, geais et pigeons ramiers. Les faînes attirent les rongeurs à l’automne, et c’est la saison où le Clan mange le mieux.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Les meilleurs grimpeurs de la forêt : ils chassent et montent la garde dans les arbres. Leur réserve de plantes médicinales est la plus riche des quatre Clans.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Les morts sont enterrés au pied d’un hêtre, et la première proie de chaque saison est déposée sur leur tombe avant que quiconque ne mange.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Crépuscule</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>Le premier sang de la guerre a coulé sur leurs rochers, et le Hêtre se souvient de ses morts. Mais le Crépuscule tient parole, et l’Assemblée sépare leurs territoires : cela suffit.</dd></div><div><dt>Clan de l’Orchidée</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Pendant la guerre, ils se sont battus contre le Hêtre comme contre tous les autres, mais toujours en face, jamais par ruse. Le Hêtre respecte des ennemis francs, et en fait volontiers des amis.</dd></div><div><dt>Clan du Brouillard</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>Leurs embuscades dans les roseaux ont coûté au Hêtre plus de guerriers que toutes les batailles à découvert. Le Hêtre n’oublie aucun tort, et la paix n’efface rien.</dd></div><div><dt>Solitaires</dt><dd>Un solitaire blessé ou affamé est soigné et nourri une nuit, puis raccompagné à la frontière.</dd></div><div><dt>Chats domestiques</dt><dd>Sous les hêtres, loin des fermes, le Hêtre n’en voit presque jamais. Il les plaint plus qu’il ne les craint.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div data-role=\"Chef\" data-n=\"1\"><dt>Chef</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Lieutenant\" data-n=\"1\"><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guérisseur\" data-n=\"2\"><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprenti guérisseur\" data-n=\"2\"><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guerriers\" data-n=\"8\"><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprentis\" data-n=\"5\"><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Reines\" data-n=\"2\"><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Chatons\" data-n=\"4\"><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Anciens\" data-n=\"3\"><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n              <div class=\"lgdc-gbc__panel\" data-clan=\"orchidee\" style=\"--g1:#c2a24f;--g2:#d1b46a\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#c2a24f;--g2:#d1b46a\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-orchidee)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan de l’Orchidée</h3><p class=\"lgdc-gbc__traits\">Courageux, francs, fougueux, colériques &amp; imprudents.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>Les prairies de la lisière</dd></div>\n                  <div><dt>Places libres</dt><dd data-lgdc-libres=\"28\">28 / 28</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Lapins, campagnols, alouettes, perdrix, et les sauterelles que les chatons apprennent à attraper en premier. On chasse à découvert, à la course.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Les meilleurs sauteurs des Clans : à découvert, ils fondent sur leurs proies d’un seul bond. Les désaccords entre guerriers se règlent par un duel devant le Clan, et l’affaire est close une fois le duel fini.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Avant une bataille, les guerriers se roulent dans le thym serpolet des pelouses pour porter tous la même odeur et se reconnaître dans la mêlée.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Crépuscule</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>Ils descendaient de leurs rochers à chaque mauvaise saison pour voler le gibier des prairies. L’Orchidée les a repoussés chaque fois, et ne leur pardonnera pas ses morts.</dd></div><div><dt>Clan du Hêtre</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Pris au milieu de la guerre, le Hêtre a tenu sur tous ses flancs sans jamais céder. L’Orchidée admire ce courage : des sages qui parlent beaucoup, mais qui tiennent parole.</dd></div><div><dt>Clan du Brouillard</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>Pendant la guerre, le Brouillard a surtout frappé ailleurs. On ne les comprend pas et on ne leur fait pas confiance, mais tant qu’ils restent dans leur marais, l’Orchidée les laisse tranquilles.</dd></div><div><dt>Solitaires</dt><dd>Jugés sur leur courage : un solitaire qui se bat bien gagne le respect du Clan.</dd></div><div><dt>Chats domestiques</dt><dd>Les prairies bordent des fermes, et leurs chats viennent parfois y chasser. L’Orchidée les chasse à son tour, et s’en moque.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div data-role=\"Chef\" data-n=\"1\"><dt>Chef</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Lieutenant\" data-n=\"1\"><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guérisseur\" data-n=\"2\"><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprenti guérisseur\" data-n=\"2\"><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guerriers\" data-n=\"8\"><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprentis\" data-n=\"5\"><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Reines\" data-n=\"2\"><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Chatons\" data-n=\"4\"><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Anciens\" data-n=\"3\"><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n              <div class=\"lgdc-gbc__panel\" data-clan=\"brouillard\" style=\"--g1:#8a99a4;--g2:#7fa39a\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#8a99a4;--g2:#7fa39a\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-brouillard)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan du Brouillard</h3><p class=\"lgdc-gbc__traits\">Rusés, discrets, débrouillards, sournois &amp; opportunistes.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>Les marais des vallons</dd></div>\n                  <div><dt>Places libres</dt><dd data-lgdc-libres=\"28\">28 / 28</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Grenouilles, poissons des ruisseaux, campagnols et poules d’eau. Le Clan chasse à l’aube, quand la brume couvre encore le marais.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Ils nagent, et se roulent dans la boue pour effacer leur odeur. Ils connaissent chaque passage sûr du marais, et laissent les autres s’y enliser.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Les noms de guerrier se donnent à l’aube, quand la brume se lève : le nouveau guerrier sort du brouillard devant le Clan réuni, et c’est la première fois qu’on l’appelle par son nom.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Crépuscule</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Forts et prévisibles : leurs patrouilles passent toujours à la même heure. Pendant la guerre, le Brouillard a préféré les avoir pour voisins que pour ennemis, et rien n’a changé.</dd></div><div><dt>Clan du Hêtre</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>Des donneurs de leçons qui ont traité le Brouillard de voleur pendant cent lunes. Le Brouillard le leur rend bien, et les roseaux se souviennent de chaque patrouille du Hêtre qui s’y est perdue.</dd></div><div><dt>Clan de l’Orchidée</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>Faciles à provoquer, donc faciles à manipuler. Pendant la guerre, le Brouillard les a souvent laissés se battre contre les autres plutôt que contre lui.</dd></div><div><dt>Solitaires</dt><dd>Des sources de nouvelles. Pendant la guerre, ils savaient avant tout le monde où les autres Clans allaient frapper. On échange avec eux plus qu’on ne les chasse.</dd></div><div><dt>Chats domestiques</dt><dd>Peu de maisons près du marais, donc peu de rencontres. Le Brouillard écoute ce qu’en racontent les solitaires : tout ce qu’on sait peut servir.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div data-role=\"Chef\" data-n=\"1\"><dt>Chef</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Lieutenant\" data-n=\"1\"><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guérisseur\" data-n=\"2\"><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprenti guérisseur\" data-n=\"2\"><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Guerriers\" data-n=\"8\"><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Apprentis\" data-n=\"5\"><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Reines\" data-n=\"2\"><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Chatons\" data-n=\"4\"><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div data-role=\"Anciens\" data-n=\"3\"><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n            </div>\n          </div>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"code\">\n        <section id=\"code-texte\">\n          <h2>Le code du guerrier</h2>\n          <ol class=\"lgdc-gb__code\"><li>Défends ton Clan, même au péril de ta vie. Tu peux être ami avec des guerriers d’autres Clans, mais ta loyauté envers ton Clan doit rester intacte.</li><li>Ne franchis pas les frontières, ne chasse pas sur les territoires des autres Clans.</li><li>Les anciens et les chatons doivent être nourris avant les apprentis et les guerriers.</li><li>Une proie n’est tuée que pour être mangée. Remercie le Clan des Étoiles pour chaque vie que tu prends.</li><li>Un chaton doit être âgé d’au moins six lunes pour devenir apprenti.</li><li>Après son baptême, un guerrier devra observer toute la nuit une veillée silencieuse.</li><li>Un guerrier ne peut devenir lieutenant s’il n’a pas formé au moins un apprenti.</li><li>Le lieutenant deviendra chef du Clan si le chef actuel meurt ou rejoint les anciens.</li><li>Lorsqu’un lieutenant meurt ou rejoint la tanière des anciens, son successeur doit être choisi avant minuit.</li><li>Une Assemblée des Clans se déroule à chaque pleine lune au cours d’une trêve qui dure toute la nuit. Toute forme de violence y est proscrite.</li><li>Les frontières doivent être inspectées et marquées tous les jours. Toute intrusion doit être punie.</li><li>Nul guerrier ne doit ignorer un chaton blessé ou en danger, même si ce chaton vient d’un Clan différent.</li><li>La parole du chef est la loi.</li><li>Un guerrier honorable n’a pas besoin de tuer son ennemi pour remporter la bataille, sauf si cet ennemi ne respecte pas lui-même le Code du guerrier, ou si c’est une question de vie ou de mort.</li><li>Un guerrier doit rejeter la vie facile d’un chat domestique.</li><li>En temps de guerre, tous doivent oublier les frontières et se battre côte à côte afin de préserver les quatre Clans.</li></ol>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"noms\">\n        <section id=\"noms-regles\">\n          <h2>Les noms</h2><div class=\"lgdc-noms\">\n  <section aria-labelledby=\"noms-chatons\">\n    <h3 id=\"noms-chatons\">Les chatons</h3>\n    <p>Le nom d’un chaton peut commencer par <b>« Petit » ou « Petite »</b>, <b>« Patte »</b> ou <b>« Boule »</b>.</p>\n  </section>\n  <section aria-labelledby=\"noms-apprentis\">\n    <h3 id=\"noms-apprentis\">Les apprentis</h3>\n    <p>Tous les noms des apprentis commencent par <b>« Nuage »</b>.</p>\n  </section>\n  <section aria-labelledby=\"noms-chefs\">\n    <h3 id=\"noms-chefs\">Les chefs</h3>\n    <p>Le nom d’un chef commence par <b>« Étoile »</b>.</p>\n  </section>\n  <section class=\"lgdc-noms__generator\" aria-labelledby=\"noms-generateur\">\n    <h3 id=\"noms-generateur\">Générateur de noms</h3>\n    <p><b>Le générateur n’est pas obligatoire</b> : tu peux tout à fait choisir le nom de ton personnage toi-même. Il est là pour t’inspirer, et ses éléments ont été triés pour rester cohérents avec l’environnement et les connaissances des Clans, afin d’éviter qu’un nom soit refusé pour une question de réalisme.</p>\n    <p>Les références à la mer, par exemple, demandent une justification cohérente dans l’histoire du personnage : nos chats vivent très loin du littoral.</p>\n    <form id=\"lgdc-noms-form\">\n      <div class=\"lgdc-noms__rang\">\n      <label for=\"lgdc-noms-rang\">Rang du personnage</label>\n      <select id=\"lgdc-noms-rang\" name=\"rang\">\n        <option value=\"chaton\">Chaton</option>\n        <option value=\"apprenti\">Apprenti</option>\n        <option value=\"guerrier\">Guerrier</option>\n        <option value=\"chef\">Chef</option>\n      </select>\n      </div>\n      <div class=\"lgdc-noms__filtres\">\n        <fieldset><legend>Pelage</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-blanc\"> <span>Blanc</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-noir\"> <span>Noir</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-gris\"> <span>Gris</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-brun\"> <span>Brun</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-roux\"> <span>Roux</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-dore\"> <span>Doré</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-creme\"> <span>Crème</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-ecaille\"> <span>Écaille de tortue</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-bicolore\"> <span>Bicolore</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-tigre\"> <span>Tigré</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-tachete\"> <span>Tacheté</span></label></div></fieldset>\n<fieldset><legend>Yeux</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-verts\"> <span>Verts</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-bleus\"> <span>Bleus</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-ambres\"> <span>Ambrés</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-cuivres\"> <span>Cuivrés</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-gris\"> <span>Gris</span></label></div></fieldset>\n<fieldset><legend>Caractère</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-gentil\"> <span>Gentil</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-calme\"> <span>Calme</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-courageux\"> <span>Courageux</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-vif\"> <span>Vif</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-discret\"> <span>Discret</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-sage\"> <span>Sage</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-farouche\"> <span>Farouche</span></label></div></fieldset>\n<fieldset><legend>Vibe de Clan</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"clan-crepuscule\"> <span>Crépuscule</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"clan-hetre\"> <span>Hêtre</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"clan-orchidee\"> <span>Orchidée</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"clan-brouillard\"> <span>Brouillard</span></label></div></fieldset>\n      </div>\n      <div class=\"lgdc-noms__actions\">\n        <button class=\"lgdc-forum-button lgdc-forum-button--primary\" type=\"submit\">Générer un nom</button>\n        <button class=\"lgdc-forum-button\" id=\"lgdc-noms-effacer\" type=\"button\">Effacer les filtres</button>\n      </div>\n      <div class=\"lgdc-noms__tirage\" aria-live=\"polite\" aria-atomic=\"true\">\n        <output id=\"lgdc-noms-resultat\">Petite Braise</output>\n        <p id=\"lgdc-noms-selection\"></p>\n      </div>\n    </form>\n    <noscript><p>Active JavaScript pour tirer un autre nom.</p></noscript>\n  </section>\n</div>\n\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"systeme\">\n        <section id=\"sys\">\n          <h2>Le système</h2>\n          <p>Le système s’inspire du <i>Warriors Adventure Game</i>, le jeu de rôle officiel de la saga, et de <i>Fabula Ultima</i>.</p>\n          <div class=\"lgdc-gbc lgdc-gbsy\">\n            <input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-personnage\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-tests\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-chasse\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-combat\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-temps\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n            <div class=\"lgdc-gbc__tabs\"><label for=\"lgdc-gbsy-personnage\">Le personnage</label><label for=\"lgdc-gbsy-tests\">Les tests</label><label for=\"lgdc-gbsy-chasse\">La chasse</label><label for=\"lgdc-gbsy-combat\">Combat et soins</label><label for=\"lgdc-gbsy-temps\">Le temps</label></div>\n            <div class=\"lgdc-gbsy__panels\"><div class=\"lgdc-gbsy__panel\" id=\"sys-personnage\" data-sub=\"personnage\" data-radio=\"lgdc-gbsy-personnage\"><div class=\"lgdc-gbs__block\"><h3>Le principe</h3><p>Sur Wildheart, on écrit d’abord. Les dés ne sont obligatoires que dans trois cas : la chasse, les portées, et les intrigues et sujets communs. Partout ailleurs, ils sont facultatifs : les joueurs d’un RP peuvent s’en servir s’ils le veulent tous, pour un combat ou un soin difficile, sinon tout s’écrit librement. Chaque test se lance avec les dés du forum, dans le message de RP : le résultat s’affiche dans le message une fois posté. Un message décrit donc une <b>tentative</b>, jamais son issue : c’est le message suivant qui raconte ce que les dés ont donné, avant de tenter sa propre action. Pour un combat, le <a href=\"/h3-suivi-de-combat\">suivi de combat</a> fait tous les calculs. <b>Un lancer ne se refait pas</b> : supprimer, reposter ou modifier les dés d’un message pour changer le résultat est interdit.</p></div><div class=\"lgdc-gbs__block\"><h3>Les quatre attributs</h3><p>Chaque attribut est noté par une taille de dé. Plus le dé est gros, plus le chat est doué : <span class=\"lgdc-dice\"><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d12</span></span></p><ul class=\"lgdc-gbs__attrs\"><li><p class=\"lgdc-gbs__attr-n\">Dextérité</p><p class=\"lgdc-gbs__attr-d\">bondir, grimper, mordre, esquiver, se faufiler</p></li><li><p class=\"lgdc-gbs__attr-n\">Intelligence</p><p class=\"lgdc-gbs__attr-d\">observer, flairer, comprendre, soigner</p></li><li><p class=\"lgdc-gbs__attr-n\">Puissance</p><p class=\"lgdc-gbs__attr-d\">se battre, plaquer, nager, encaisser</p></li><li><p class=\"lgdc-gbs__attr-n\">Volonté</p><p class=\"lgdc-gbs__attr-d\">tenir bon, feuler, convaincre, affronter la peur</p></li></ul></div><div class=\"lgdc-gbs__block\"><h3>Les dés selon le rang</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Rang</th><th scope=\"col\">Répartition au choix</th></tr></thead><tbody><tr><td>Chaton</td><td><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span></span></td></tr><tr><td>Apprenti</td><td><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d6</span></span><span class=\"lgdc-gbs__or\">ou</span><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span></span></td></tr><tr><td>Guerrier, guérisseur, lieutenant, chef</td><td><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span></span><span class=\"lgdc-gbs__or\">ou</span><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d6</span></span><span class=\"lgdc-gbs__or\">ou</span><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span></span></td></tr><tr><td>Ancien</td><td>comme un guerrier, puis Dextérité et Puissance perdent une taille (d8 au plus), et Intelligence ou Volonté en gagne une</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Points de vie et esquive</h3><dl class=\"lgdc-gbs__facts\"><div><dt>Points de vie</dt><dd>dé de Puissance + 5 (chaton), + 10 (apprenti) ou + 15 (guerrier, ancien et plus)</dd></div><div><dt>Esquive</dt><dd>la taille du dé de Dextérité + 2</dd></div></dl></div><div class=\"lgdc-gbs__block\"><h3>La capacité de Clan</h3><ul class=\"lgdc-gbs__clans\"><li style=\"--g1:#8e7f9a\"><span class=\"lgdc-gbr__clan\">Crépuscule</span><b>+1 en Guetter</b></li><li style=\"--g1:#b07a4f\"><span class=\"lgdc-gbr__clan\">Hêtre</span><b>+1 en Grimper, et en Mordre à la chasse</b></li><li style=\"--g1:#c2a24f\"><span class=\"lgdc-gbr__clan\">Orchidée</span><b>+1 en Bondir</b></li><li style=\"--g1:#8a99a4\"><span class=\"lgdc-gbr__clan\">Brouillard</span><b>+1 en Se faufiler</b></li></ul></div><div class=\"lgdc-gbs__block\"><h3>Les capacités de rôle</h3><p>Elles s’ajoutent aux astuces. Les rôles ne donnent pas de meilleurs dés. Un premier personnage peut être créé directement guérisseur, lieutenant ou chef : son passé remplit ces conditions dans son histoire. Seul l’âge minimum compte.</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Rôle</th><th scope=\"col\">Capacité</th><th scope=\"col\">Condition</th></tr></thead><tbody><tr><td>Lieutenant</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Organiser les patrouilles\" title=\"Une fois par sujet : un camarade de Clan relance un test.\">Organiser les patrouilles</b></td><td>Avoir au moins 24 lunes, être guerrier et avoir formé au moins un apprenti.</td></tr><tr><td>Chef</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Neuf vies\" title=\"Perd une vie au lieu de tomber, et se relève avec la moitié de ses points de vie.\">Neuf vies</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"La parole du chef\" title=\"Une fois par sujet : +2 pour Convaincre ou Tenir bon face à son Clan.\">La parole du chef</b></td><td>Avoir au moins 30 lunes et avoir été lieutenant.</td></tr><tr><td>Guérisseur</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Lire les signes\" title=\"Comme l’astuce du même nom, mais sans test et sans limite par sujet.\">Lire les signes</b></td><td>Avoir au moins 12 lunes et avoir été apprenti guérisseur. Une place se libère quand un des deux guérisseurs meurt ou rejoint les anciens.</td></tr></tbody></table></div><p>Un guerrier peut devenir mentor à partir de 15 lunes. Le guérisseur et le chef n’ont pas d’âge de retraite : ils gardent leur rôle tant qu’ils le peuvent, et leur joueur décide du moment où ils rejoignent les anciens. Pour les autres, voir <a href=\"#temps\">les âges</a>.</p></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-tests\" data-sub=\"tests\" data-radio=\"lgdc-gbsy-tests\"><div class=\"lgdc-gbs__block\"><h3>Le test</h3><p>On lance <b>les deux dés du geste</b>, on additionne avec les bonus éventuels, et on réussit si le total atteint la difficulté.</p><ol class=\"lgdc-gbs__ladder\"><li><b>5</b><span class=\"lgdc-micro\">Très facile</span></li><li><b>7</b><span class=\"lgdc-micro\">Facile</span></li><li><b>10</b><span class=\"lgdc-micro\">Moyen</span></li><li><b>13</b><span class=\"lgdc-micro\">Difficile</span></li><li><b>16</b><span class=\"lgdc-micro\">Très difficile</span></li></ol></div><div class=\"lgdc-gbs__block\"><h3>Les gestes</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--gestes\"><thead><tr><th scope=\"col\">Geste</th><th scope=\"col\">Dés à lancer</th></tr></thead><tbody><tr><td>Guetter (voir, écouter, flairer)</td><td>Intelligence + Volonté</td></tr><tr><td>Pister, Réfléchir</td><td>Intelligence + Intelligence</td></tr><tr><td>Se faufiler</td><td>Dextérité + Volonté</td></tr><tr><td>Bondir (assaut, proie)</td><td>Dextérité + Intelligence</td></tr><tr><td>Frapper (coup de patte)</td><td>Puissance + Puissance</td></tr><tr><td>Grimper</td><td>Dextérité + Puissance</td></tr><tr><td>Mordre</td><td>Puissance + Dextérité</td></tr><tr><td>Nager</td><td>Puissance + Volonté</td></tr><tr><td>Feuler, gonfler le dos</td><td>Volonté + Puissance</td></tr><tr><td>Soigner</td><td>Intelligence + Volonté</td></tr><tr><td>Convaincre</td><td>Volonté + Intelligence</td></tr><tr><td>Tenir bon (peur, douleur)</td><td>Volonté + Volonté</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Critiques et échecs</h3><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Double de 6 ou plus</b> : critique, c’est une réussite avec un avantage au choix : +2 au prochain test d’un allié, ou une altération infligée à l’adversaire.<br><b>Double 1</b> : échec spectaculaire, et ça tourne mal.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les liens</h3><p>Un chat peut avoir autant de liens qu’il veut, avec un personnage ou un groupe. Chaque lien porte au plus une émotion par paire :</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--pairs\"><thead><tr><th scope=\"col\"></th><th scope=\"col\"></th></tr></thead><tbody><tr><td>admiration</td><td>mépris</td></tr><tr><td>loyauté</td><td>méfiance</td></tr><tr><td>affection</td><td>haine</td></tr></tbody></table></div><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Un RP terminé = une émotion gagnée</b> envers un personnage de ce RP. L’émotion opposée remplace l’ancienne.<br>Quand le chat agit pour ou contre la personne liée : <b>+1 par émotion</b>, automatiquement, une fois par sujet.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les astuces</h3><p>Les astuces se rangent en <b>cinq voies</b>, chacune sur trois rangs. Une astuce de rang II demande une astuce de rang I de la même voie, et celle de rang III demande les deux astuces de rang II. Un apprenti en a 1, un guerrier 3, puis chaque amélioration peut en ajouter une. Une astuce marquée ×2 peut se prendre deux fois : chaque niveau compte comme une astuce.</p><p>Une astuce marquée <b>Toujours</b> agit en permanence, les autres s’utilisent <b>une fois par sujet</b>. Elles se déclarent dans le message, avant que les dés ne s’affichent : si le coup rate, l’astuce n’est pas dépensée.</p><div class=\"lgdc-gbv\" style=\"--tc:#b5654a\"><header><h4>Griffe</h4><span>le combat</span></header><div class=\"lgdc-gbv__cols\"><div><p class=\"lgdc-gbv__rank\">Rang I</p><ul><li><b>Coup puissant</b><span class=\"lgdc-gbv__tag\">×2</span><p>+4 dégâts par niveau sur un coup.</p></li><li><b>Plaquage</b><p>Un coup qui touche ralentit aussi la cible.</p></li><li><b>Riposte</b><p>Quand une attaque le rate, son coup suivant touche sans test.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang II</p><ul><li><b>Griffes au ventre</b><span class=\"lgdc-gbv__tag\">Toujours</span><p>+3 dégâts contre une cible ralentie ou en crise.</p></li><li><b>Rage du sang</b><span class=\"lgdc-gbv__tag\">Toujours</span><p>En crise, +2 pour Frapper, Bondir et Mordre.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang III</p><ul><li><b>Furie</b><p>Deux attaques dans le même tour.</p></li></ul></div></div></div><div class=\"lgdc-gbv\" style=\"--tc:#8c8a4f\"><header><h4>Chasse</h4><span>la proie</span></header><div class=\"lgdc-gbv__cols\"><div><p class=\"lgdc-gbv__rank\">Rang I</p><ul><li><b>Bond mortel</b><span class=\"lgdc-gbv__tag\">×2</span><p>+1 point par niveau sur une chasse réussie.</p></li><li><b>Pistage</b><span class=\"lgdc-gbv__tag\">Toujours</span><p>+2 pour Pister ou Réfléchir.</p></li><li><b>Flair</b><p>Si la chasse échoue à l’étape Guetter, relancer la chasse.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang II</p><ul><li><b>Partage du gibier</b><p>Une chasse réussie retire l’altération affaibli à tous les camarades du RP.</p></li><li><b>Patte légère</b><p>Si la chasse échoue à l’étape Se faufiler ou Bondir, relancer la chasse.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang III</p><ul><li><b>Traque</b><span class=\"lgdc-gbv__tag\">Toujours</span><p>Ses chasses réussies rapportent le double de points.</p></li></ul></div></div></div><div class=\"lgdc-gbv\" style=\"--tc:#6f6a86\"><header><h4>Ombre</h4><span>la ruse</span></header><div class=\"lgdc-gbv__cols\"><div><p class=\"lgdc-gbv__rank\">Rang I</p><ul><li><b>Effacer son odeur</b><span class=\"lgdc-gbv__tag\">Toujours</span><p>−2 pour qui le piste.</p></li><li><b>Feinte</b><p>Le coup touche sans test.</p></li><li><b>Tromperie</b><span class=\"lgdc-gbv__tag\">×2</span><p>+2 par niveau pour Convaincre en mentant ou en dupant.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang II</p><ul><li><b>Embuscade</b><p>Le premier coup d’un combat touche sans test et fait +5 dégâts.</p></li><li><b>Démasquer</b><p>Après un test de Réfléchir réussi, le joueur de la cible lui confie ce que son personnage cherche vraiment.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang III</p><ul><li><b>Ombre parmi les ombres</b><p>Fuir sans test et sans laisser de trace : personne ne peut le pister jusqu’à la fin du sujet.</p></li></ul></div></div></div><div class=\"lgdc-gbv\" style=\"--tc:#b0894f\"><header><h4>Cœur</h4><span>le Clan</span></header><div class=\"lgdc-gbv__cols\"><div><p class=\"lgdc-gbv__rank\">Rang I</p><ul><li><b>Vigilance</b><span class=\"lgdc-gbv__tag\">Toujours</span><span class=\"lgdc-gbv__tag\">×2</span><p>+1 par niveau pour Guetter.</p></li><li><b>Rempart</b><p>Prendre les dégâts d’un camarade.</p></li><li><b>Feulement</b><p>La cible est effrayée, sans test.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang II</p><ul><li><b>Inébranlable</b><span class=\"lgdc-gbv__tag\">Toujours</span><p>+5 points de vie, et jamais effrayé.</p></li><li><b>Parole d’Assemblée</b><span class=\"lgdc-gbv__tag\">Toujours</span><p>+2 pour Convaincre ou Feuler face à un autre Clan.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang III</p><ul><li><b>Ralliement</b><p>Chaque camarade présent relance un test raté, puis gagne +2 à son prochain test.</p></li></ul></div></div></div><div class=\"lgdc-gbv\" style=\"--tc:#6e8f6a\"><header><h4>Herbe</h4><span>le soin</span></header><div class=\"lgdc-gbv__cols\"><div><p class=\"lgdc-gbv__rank\">Rang I</p><ul><li><b>Connaissance des plantes</b><span class=\"lgdc-gbv__tag\">Toujours</span><span class=\"lgdc-gbv__tag\">×2</span><p>+1 par niveau pour Soigner.</p></li><li><b>Apaiser</b><p>Retire une altération d’Intelligence ou de Volonté : désorienté, effrayé ou enragé.</p></li><li><b>Lire les signes</b><p>Après un test de Réfléchir réussi (difficulté 10), interpréter un rêve ou un présage.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang II</p><ul><li><b>Main sûre</b><p>Un soin rend tous les points de vie et retire toutes les altérations.</p></li><li><b>Messager des Étoiles</b><p>Une fois par lune, demander au staff un vrai présage du Clan des Étoiles pour l’intrigue.</p></li></ul></div><div><p class=\"lgdc-gbv__rank\">Rang III</p><ul><li><b>Souffle des Étoiles</b><p>Un camarade qui tombe à 0 point de vie reste à 1 point de vie et peut agir.</p></li></ul></div></div></div></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-chasse\" data-sub=\"chasse\" data-radio=\"lgdc-gbsy-chasse\"><div class=\"lgdc-gbs__block\"><h3>Les quatre étapes</h3><p>Une chasse se lance en une fois : le bouton <b>Lancer une chasse</b> de l’éditeur ajoute le dé Chasse du territoire, qui tire la proie, puis les deux dés de chaque étape. Le message déroule les quatre tests, dans l’ordre, contre la difficulté de cette proie. <b>Chaque chasseur peut lancer une chasse quand il termine un RP</b>, dans son dernier message du sujet. Seuls les apprentis guerriers, les guerriers, le lieutenant et le chef chassent : les chatons, les reines, les guérisseurs, leurs apprentis et les anciens sont nourris par le Clan.</p><ol class=\"lgdc-gbs__steps\"><li><span class=\"lgdc-micro\">Étape 1</span><b>Guetter</b><span>repérer la proie</span></li><li><span class=\"lgdc-micro\">Étape 2</span><b>Se faufiler</b><span>l’approcher</span></li><li><span class=\"lgdc-micro\">Étape 3</span><b>Bondir</b><span>l’attraper</span></li><li><span class=\"lgdc-micro\">Étape 4</span><b>Mordre</b><span>la tuer</span></li></ol><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Au premier échec, la proie s’enfuit.</b> Un critique permet de sauter l’étape suivante.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les proies de la réserve</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--num\"><thead><tr><th scope=\"col\">Proie</th><th scope=\"col\">Guetter</th><th scope=\"col\">Se faufiler</th><th scope=\"col\">Bondir</th><th scope=\"col\">Mordre</th><th scope=\"col\">Points</th></tr></thead><tbody><tr><td>Campagnol, mulot</td><td>7</td><td>5</td><td>5</td><td>5</td><td>2</td></tr><tr><td>Grenouille, lézard</td><td>7</td><td>5</td><td>7</td><td>5</td><td>2</td></tr><tr><td>Oiseau</td><td>5</td><td>7</td><td>10</td><td>5</td><td>2</td></tr><tr><td>Écureuil</td><td>5</td><td>7</td><td>10</td><td>5</td><td>4</td></tr><tr><td>Poisson</td><td>7</td><td>5</td><td>10</td><td>5</td><td>4</td></tr><tr><td>Lapin</td><td>5</td><td>10</td><td>10</td><td>7</td><td>6</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>La proie du territoire</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--num\"><thead><tr><th scope=\"col\">Territoire</th><th scope=\"col\">Campagnol, mulot</th><th scope=\"col\">Grenouille, lézard</th><th scope=\"col\">Oiseau</th><th scope=\"col\">Écureuil</th><th scope=\"col\">Poisson</th><th scope=\"col\">Lapin</th></tr></thead><tbody><tr><td>Crépuscule</td><td>01–35</td><td>36–60</td><td>61–85</td><td>—</td><td>—</td><td>86–00</td></tr><tr><td>Hêtre</td><td>01–40</td><td>—</td><td>41–70</td><td>71–00</td><td>—</td><td>—</td></tr><tr><td>Orchidée</td><td>01–40</td><td>—</td><td>41–85</td><td>—</td><td>—</td><td>86–00</td></tr><tr><td>Brouillard</td><td>36–55</td><td>01–35</td><td>56–70</td><td>—</td><td>71–00</td><td>—</td></tr></tbody></table></div><p>Hors de la réserve, le staff indique la proie selon le lieu.</p></div><div class=\"lgdc-gbs__block\"><h3>La pile de gibier du Clan</h3><p>Chaque chasse réussie <b>sur son propre territoire</b> rapporte au Clan les points de la proie. On chasse à la fin de chaque RP terminé, sans limite par lune. Le joueur l’indique en fin de message : <code>Chasse : lapin (+6)</code>. Le compteur des quatre Clans est affiché dans les annonces.</p><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Objectif : 1 point par membre joué et par lune.</b><br>Objectif raté : tous les membres du Clan commencent la lune suivante <b>affaiblis</b>. Un remède ou une chasse réussie retire l’altération, chat par chat.</p></aside></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-combat\" data-sub=\"combat\" data-radio=\"lgdc-gbsy-combat\"><div class=\"lgdc-gbs__block\"><h3>L’attaque</h3><dl class=\"lgdc-gbs__facts\"><div><dt>Premier coup</dt><dd>celui qui provoque le combat frappe en premier, dès son premier message. Ensuite, on alterne : un message, un coup.</dd></div><div><dt>Toucher</dt><dd>le test de Frapper, Bondir ou Mordre doit atteindre l’esquive de la cible</dd></div><div><dt>Dégâts</dt><dd>la valeur du plus haut des deux dés + 5 (griffes ou crocs)</dd></div></dl><p>Le <a href=\"/h3-suivi-de-combat\">suivi de combat</a> donne la balise de dés de chaque coup, puis calcule les dégâts, la crise, les altérations et les astuces dépensées.</p></div><div class=\"lgdc-gbs__block\"><h3>Tomber</h3><p>Sous la moitié de ses points de vie, le chat est <b>en crise</b> : ses blessures se voient, et son joueur peut le faire fuir ou se rendre sans attendre 0. À 0, il choisit :</p><ul class=\"lgdc-gbs__cards\"><li><b>Se rendre</b><span>Le chat est hors de combat, avec une conséquence pour l’histoire.</span></li><li><b>Se sacrifier</b><span>Un dernier geste, puis il rejoint le Clan des Étoiles.</span></li><li><b>Un chef</b><span>Perd une de ses neuf vies au lieu de tomber, et se relève avec la moitié de ses points de vie. À sa dernière vie, il tombe comme les autres.</span></li></ul></div><div class=\"lgdc-gbs__block\"><h3>Les altérations</h3><p>Une altération fait baisser un ou deux dés d’une taille, jusqu’à ce qu’elle soit soignée. Deux altérations différentes qui touchent le même dé se cumulent, mais la même altération reçue deux fois ne fait rien de plus. Un dé ne descend jamais sous d6 : une altération qui touche un d6 donne −2 aux tests de ce dé.</p><p>Elles viennent du combat (Plaquage ralentit, Feulement effraie, un critique peut infliger l’altération de son choix), d’un choc ou d’une chute (désorienté), d’une perte ou d’une humiliation (enragé), de la faim (affaibli, voir la pile de gibier) ou d’une plante toxique (empoisonné, voir Les remèdes).</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Altération</th><th scope=\"col\">Dé touché</th><th scope=\"col\">Remèdes</th></tr></thead><tbody><tr><td>Ralenti</td><td>Dextérité</td><td>consoude, feuilles de sureau, ortie, pâquerette</td></tr><tr><td>Désorienté</td><td>Intelligence</td><td>aspérule odorante, camomille, menthe aquatique, primevère officinale</td></tr><tr><td>Affaibli</td><td>Puissance</td><td>baies de genièvre, cresson de fontaine, miel, pâquerette, pimprenelle</td></tr><tr><td>Effrayé</td><td>Volonté</td><td>aubépine, houblon, thym serpolet, tilleul, valériane</td></tr><tr><td>Enragé</td><td>Dextérité et Intelligence</td><td>graines de pavot, houblon, thym serpolet, tilleul, valériane</td></tr><tr><td>Empoisonné</td><td>Puissance et Volonté</td><td>achillée mille-feuille, ortie</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Les soins</h3><p>Une fois par sujet, le guérisseur fait un test de <b>Soigner</b>. S’il réussit, le blessé récupère la valeur du plus haut dé + 5 points de vie, et le remède adapté retire l’altération. Les remèdes sont décrits dans <a href=\"#remedes\">Les remèdes</a>.</p><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p>Au début de chaque nouveau sujet, un chat retrouve <b>tous ses points de vie</b>, sauf s’il garde une blessure grave décidée en RP.</p></aside></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-temps\" data-sub=\"temps\" data-radio=\"lgdc-gbsy-temps\"><div class=\"lgdc-gbs__block\"><h3>L’évaluation des apprentis</h3><p>Pour devenir guerrier, un apprenti doit remplir trois conditions : avoir plus de 12 lunes, avoir terminé un RP avec son mentor, et avoir réussi une chasse. Le passage se fait ensuite en RP et est validé par le staff.</p></div><div class=\"lgdc-gbs__block\"><h3>La progression</h3><p>Les personnages progressent avec le temps, tous au même rythme.</p><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Toutes les 3 lunes depuis la validation de la fiche : une amélioration.</b><br>Au choix : une astuce de plus, +2 sur un geste (jusqu’à +4), ou un dé qui gagne une taille.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les plafonds</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Rang</th><th scope=\"col\">Dé maximum</th><th scope=\"col\">Astuces maximum</th></tr></thead><tbody><tr><td>Chaton</td><td><span class=\"lgdc-die\">d8</span></td><td>1</td></tr><tr><td>Apprenti</td><td><span class=\"lgdc-die\">d10</span></td><td>3</td></tr><tr><td>Guerrier, guérisseur, lieutenant, chef</td><td><span class=\"lgdc-die\">d12</span></td><td>6</td></tr><tr><td>Ancien</td><td><span class=\"lgdc-die\">d12</span> Intelligence et Volonté, <span class=\"lgdc-die\">d8</span> Dextérité et Puissance</td><td>6</td></tr></tbody></table></div><p>Ce qui dépasse le plafond est gardé jusqu’au changement de rang, qui se fait en RP et est validé par le staff.</p></div><div class=\"lgdc-gbs__block\"><h3>Les personnages créés plus âgés</h3><p>Une amélioration par tranche de 12 lunes au-delà de 12 lunes, avec un maximum de 4.</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--num\"><thead><tr><th scope=\"col\">Âge à la création</th><th scope=\"col\">12–23</th><th scope=\"col\">24–35</th><th scope=\"col\">36–47</th><th scope=\"col\">48–59</th><th scope=\"col\">60 et +</th></tr></thead><tbody><tr><td>Améliorations</td><td>0</td><td>1</td><td>2</td><td>3</td><td>4</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Les portées</h3><p>Une fois par lune, une chatte de plus de 12 lunes qui n’est plus apprentie peut avoir une portée, si les deux joueurs du couple sont d’accord et si elle n’est ni pleine ni reine. Le dé <b>Portée</b> tire d’abord la tentative : de 01 à 50, la chatte n’attend pas de petits cette lune, et le couple pourra réessayer à la suivante. Sinon, il tire le nombre de chatons :</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--num\"><thead><tr><th scope=\"col\">d100</th><th scope=\"col\">01–08</th><th scope=\"col\">09–25</th><th scope=\"col\">26–50</th><th scope=\"col\">51–75</th><th scope=\"col\">76–92</th><th scope=\"col\">93–00</th></tr></thead><tbody><tr><td>Chatons</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td></tr></tbody></table></div><p>Les chatons naissent dans le Clan de leur mère. Le staff donne à chaque chaton une apparence générale selon la génétique des parents. La chatte reste pleine 2 lunes : les chatons naissent à la deuxième pleine lune après la tentative. Elle est ensuite reine jusqu’à ce qu’ils deviennent apprentis, à 6 lunes, puis reprend son rang. Elle ne peut pas tenter de nouvelle portée tant qu’elle est pleine ou reine. Les chatons d’un parent joué ne comptent pas dans les places du Clan.</p></div></div></div>\n          </div>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"remedes\">\n        <section id=\"remedes-liste\">\n          <h2>Les remèdes</h2>\n          <p>Les guérisseurs ne cueillent que ce qui pousse dans la réserve et à ses lisières. Chaque plante est rangée sur le territoire où on la trouve le plus souvent, avec son usage.</p>\n          <div class=\"lgdc-gbc lgdc-gbr\">\n            <input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-crepuscule\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-hetre\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-orchidee\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-brouillard\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-partout\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n            <div class=\"lgdc-gbc__tabs\"><label for=\"lgdc-gbr-crepuscule\" style=\"--g1:#8e7f9a\">Crépuscule</label><label for=\"lgdc-gbr-hetre\" style=\"--g1:#b07a4f\">Hêtre</label><label for=\"lgdc-gbr-orchidee\" style=\"--g1:#c2a24f\">Orchidée</label><label for=\"lgdc-gbr-brouillard\" style=\"--g1:#8a99a4\">Brouillard</label><label for=\"lgdc-gbr-partout\" style=\"--g1:#7d766d\">Partout</label></div>\n            <div class=\"lgdc-gbr__panels\"><div class=\"lgdc-gbr__panel\" data-cat=\"crepuscule\" style=\"--g1:#8e7f9a\"><p class=\"lgdc-gbr__where\">Ce qui pousse sur les rochers du plateau, le territoire du Clan du Crépuscule.</p><ul class=\"lgdc-gbr__list\"><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus%20communis%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-082.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Baies de genièvre</b><i class=\"lgdc-gbr__lat\">Juniperus communis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Sur le plateau, entre les rochers</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Baies bleu-pourpre d’un genévrier, buisson aux aiguilles piquantes vert foncé. Forte odeur.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Redonnent des forces, aident à respirer et apaisent les maux de ventre. Calment aussi les chats.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher puis manger. En cataplasme.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Taxus%20baccata0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Baies d’if</b><i class=\"lgdc-gbr__lat\">Taxus baccata</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Dans l’éboulis, à l’ombre des parois</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Baie rouge-rose à l’intérieur noir.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Tue un chat en quelques minutes.</dd></div><div><dt>L’utiliser</dt><dd>Aucun, sauf pour abréger les souffrances d’un chat qu’on ne peut plus sauver.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Chelidonium%20majus0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Chélidoine</b><i class=\"lgdc-gbr__lat\">Chelidonium majus</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Au pied des parois de calcaire</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Une plante à fleur jaune qui a quatre pétales.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Apaise et répare les yeux blessés.</dd></div><div><dt>L’utiliser</dt><dd>Le jus doit pénétrer dans l’œil.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Nepeta%20cataria%20Sturm24.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Herbe à chat</b><i class=\"lgdc-gbr__lat\">Nepeta cataria</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans l’éboulis</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante à l’odeur délicieuse et attirante. Ses feuilles, douces au toucher, ressemblent à celles de l’ortie mais ne piquent pas. Le gel la brûle facilement.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soigne le mal blanc et le mal vert, qui peut être mortel pour les chatons et les anciens. Dangereuse à forte dose.</dd></div><div><dt>L’utiliser</dt><dd>Doit être mangée.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Origanum%20vulgare0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Origan</b><i class=\"lgdc-gbr__lat\">Origanum vulgare</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Sur les pentes sèches du plateau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante velue des pentes sèches, aux petites fleurs roses en bouquets, très parfumée quand on froisse ses feuilles.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme la toux et les maux de ventre.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles et les fleurs.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Sanguisorba%20minor0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Pimprenelle</b><i class=\"lgdc-gbr__lat\">Sanguisorba minor</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans l’herbe rase du plateau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante à multiples feuilles vertes ondulées.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Herbe fortifiante. Donne des forces.</dd></div><div><dt>L’utiliser</dt><dd>Manger.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Primula%20veris0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Primevère officinale</b><i class=\"lgdc-gbr__lat\">Primula veris</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans l’herbe rase du plateau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petites clochettes jaune d’or penchées en bouquet au bout d’une tige, dans l’herbe rase, à la saison des feuilles nouvelles.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme la toux, chasse les vertiges et aide à dormir.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les fleurs, ou la racine pour une toux tenace.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Salvia%20pratensis0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Sauge des prés</b><i class=\"lgdc-gbr__lat\">Salvia pratensis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Sur les pentes sèches du plateau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Grands épis de fleurs bleu-violet en forme de gueule ouverte, au-dessus de feuilles ridées à l’odeur forte.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Apaise les maux de gorge et les gencives enflées.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Asplenium%20scolopendrium0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Scolopendre</b><i class=\"lgdc-gbr__lat\">Asplenium scolopendrium</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">À l’entrée de la grotte</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fougère aux longues feuilles entières et luisantes, en forme de langue, qui pousse dans l’ombre fraîche des pierres.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Aide les plaies à se refermer et calme la toux.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles en pulpe et l’appliquer sur la plaie.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Thymus%20serpyllum%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-138.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Thym serpolet</b><i class=\"lgdc-gbr__lat\">Thymus serpyllum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Entre les pierres chaudes du plateau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petite plante rampante aux tiges brunes, aux feuilles vert clair et aux fleurs roses.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme l’angoisse, la nervosité et la colère, surtout chez un chat en état de choc.</dd></div><div><dt>L’utiliser</dt><dd>Faire respirer.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Tussilago%20farfara%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-142.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Tussilage</b><i class=\"lgdc-gbr__lat\">Tussilago farfara</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans l’éboulis</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleurs jaunes semblables à celles du pissenlit, qui sortent avant les feuilles. Pousse surtout à la saison des feuilles nouvelles.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Facilite la respiration et soigne la « toux des chatons ». Soigne aussi les coussinets craquelés ou douloureux.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles pour en faire une pulpe à avaler ou en faire un cataplasme.</dd></div></dl></div></li></ul></div><div class=\"lgdc-gbr__panel\" data-cat=\"hetre\" style=\"--g1:#b07a4f\"><p class=\"lgdc-gbr__where\">Ce qui pousse sur la futaie de hêtres, le territoire du Clan du Hêtre.</p><ul class=\"lgdc-gbr__list\"><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Allium%20ursinum0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Ail des ours</b><i class=\"lgdc-gbr__lat\">Allium ursinum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Près de la source du Hêtre</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Odeur d’ail très forte et piquante. Pousse en touffes, avec un bulbe blanc, de larges feuilles vertes et des fleurs blanches en étoile.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soigne les infections, surtout celles des morsures de rat, et masque les odeurs.</dd></div><div><dt>L’utiliser</dt><dd>Se rouler dedans.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Galium%20odorata0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Aspérule odorante</b><i class=\"lgdc-gbr__lat\">Galium odoratum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petites fleurs blanches en étoile, feuilles en collerette. Sent le foin une fois séchée.</dd></div><div><dt>À quoi elle sert</dt><dd>Parfume les nids et éloigne les puces. Mâchée, elle calme les maux de tête et remet les idées en place.</dd></div><div><dt>L’utiliser</dt><dd>Glisser dans la litière, ou mâcher quelques feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Ilex%20aquifolium0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Baies de houx</b><i class=\"lgdc-gbr__lat\">Ilex aquifolium</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Arbrisseau aux feuilles épineuses et aux baies rouges.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Poison. Tue un chat en quelques minutes.</dd></div><div><dt>L’utiliser</dt><dd>Aucun.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Atropa%20belladonna%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-018.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Belladone</b><i class=\"lgdc-gbr__lat\">Atropa belladonna</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Dans la clairière</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petit arbuste aux fleurs en cloche, dont les baies sont noires et brillantes à maturité.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Délire, puis mort.</dd></div><div><dt>L’utiliser</dt><dd>Aucun : ses baies tuent.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Daphne%20mezereum%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-050.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Bois-joli</b><i class=\"lgdc-gbr__lat\">Daphne mezereum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petit arbuste aux fleurs roses qui s’ouvrent avant les feuilles, baies rouges.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Brûlures de la bouche, convulsions, mort.</dd></div><div><dt>L’utiliser</dt><dd>Aucun.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Ajuga%20reptans0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Bugle rampante</b><i class=\"lgdc-gbr__lat\">Ajuga reptans</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans la clairière</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante basse aux épis de fleurs bleues, qui court sur le sol.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Aide les plaies à cicatriser.</dd></div><div><dt>L’utiliser</dt><dd>Cataplasme de feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/35%20Digitalis%20lutea%20-%20John%20Lindley%20-%20Collectanea%20botanica%20%281821%29.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Digitale jaune</b><i class=\"lgdc-gbr__lat\">Digitalis lutea</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Au bord de la clairière</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Hautes tiges couvertes de petites cloches jaune pâle.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Ralentit le cœur jusqu’à l’arrêter.</dd></div><div><dt>L’utiliser</dt><dd>Aucun : les graines tuent.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Quercus%20robur0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Feuilles de chêne</b><i class=\"lgdc-gbr__lat\">Quercus robur</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, là où les chênes se mêlent aux hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Feuilles mortes, sèches et ondulées.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soigne les infections.</dd></div><div><dt>L’utiliser</dt><dd>Faire sécher les feuilles et les garder au sec. Les mâcher en cataplasme épais et l’étaler sur la blessure.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Rubus%20idaeus%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-124.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Feuilles de framboisier</b><i class=\"lgdc-gbr__lat\">Rubus idaeus</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans la clairière</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Feuilles aux bords dentelés et douces au toucher.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Apaise la douleur et peut arrêter les saignements pendant la mise bas.</dd></div><div><dt>L’utiliser</dt><dd>Manger la pulpe des feuilles ou les mâcher. Appuyer sur la plaie avec les feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Hedera%20helix0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Feuilles de lierre</b><i class=\"lgdc-gbr__lat\">Hedera helix</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Sur les troncs, autour du vieux hêtre</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Feuilles en forme d’étoiles ou ovales.</dd></div><div><dt>À quoi elle sert</dt><dd>Sert à emballer les remèdes pour les conserver.</dd></div><div><dt>L’utiliser</dt><dd>Emballer des remèdes.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Sambucus%20nigra%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-127.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Feuilles de sureau</b><i class=\"lgdc-gbr__lat\">Sambucus nigra</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, en lisière de la futaie</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Feuilles à l’extrémité pointue et au bord denté.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soulage les problèmes d’articulations.</dd></div><div><dt>L’utiliser</dt><dd>Utilisées en cataplasme.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Fragaria%20vesca0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Fraisier des bois</b><i class=\"lgdc-gbr__lat\">Fragaria vesca</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans la clairière</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petite plante basse des clairières, aux feuilles dentées par trois, aux fleurs blanches et aux minuscules fraises rouges.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Les feuilles arrêtent les diarrhées.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles et avaler le jus.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Galium%20aparine0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Gaillet gratteron</b><i class=\"lgdc-gbr__lat\">Galium aparine</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, en lisière de la futaie</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante aux fruits ronds et verts, couverts de poils crochus.</dd></div><div><dt>À quoi elle sert</dt><dd>Aide à maintenir les cataplasmes en place sans blesser la peau.</dd></div><div><dt>L’utiliser</dt><dd>Utiliser les fruits.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Bijen%20en%20wespen%20X%2C%20RP-P-1896-A-19368-677.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Miel</b><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans le creux du vieux hêtre</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Liquide doré et sucré produit par les abeilles.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Redonne des forces, surtout aux reines lors de la mise bas. Apaise aussi les maux de gorge et aide à respirer quand on a inhalé de la fumée.</dd></div><div><dt>L’utiliser</dt><dd>Manger, ou déposer sur une blessure.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Convallaria%20majalis%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-045.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Muguet</b><i class=\"lgdc-gbr__lat\">Convallaria majalis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petites clochettes blanches parfumées, baies rouges en été.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Vomissements, cœur affolé, parfois la mort.</dd></div><div><dt>L’utiliser</dt><dd>Aucun.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Paris%20quadrifolia0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Parisette</b><i class=\"lgdc-gbr__lat\">Paris quadrifolia</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Près de la source du Hêtre</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Une seule tige, quatre feuilles en croix, une fleur verdâtre puis une baie bleu-noir posée au centre.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Vomissements, vertiges, cœur ralenti.</dd></div><div><dt>L’utiliser</dt><dd>Aucun.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Pulmonaria%20officinalis0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Pulmonaire</b><i class=\"lgdc-gbr__lat\">Pulmonaria officinalis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleurs roses puis bleues, larges feuilles vert foncé tachées de blanc.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soigne le mal jaune.</dd></div><div><dt>L’utiliser</dt><dd>Manger les feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Rubus%20caesius0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Ronce</b><i class=\"lgdc-gbr__lat\">Rubus fruticosus</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans la clairière</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante à fleurs blanc-rosé à cinq pétales. Pousse dans les zones ensoleillées. Les feuilles dégagent une odeur piquante.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Apaise la douleur des piqûres d’abeille.</dd></div><div><dt>L’utiliser</dt><dd>Faire des feuilles un cataplasme.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Sanicula%20europaea0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Sanicle</b><i class=\"lgdc-gbr__lat\">Sanicula europaea</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Feuilles luisantes en main ouverte, petites boules de fleurs blanches.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Arrête les saignements et referme les plaies.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles et les appliquer.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Polygonatum%20multiflorum0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Sceau-de-Salomon</b><i class=\"lgdc-gbr__lat\">Polygonatum multiflorum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Longue tige arquée, des clochettes blanches pendues sous les feuilles, puis des baies noires.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>La racine fait dégonfler les bosses et les bleus. Les baies sont toxiques.</dd></div><div><dt>L’utiliser</dt><dd>Écraser la racine en cataplasme sur la bosse. Ne jamais manger les baies.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Fagus%20sylvatica%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-060.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Sève de hêtre</b><i class=\"lgdc-gbr__lat\">Fagus sylvatica</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Sur le vieux hêtre</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Sève d’un grand et vieil arbre à l’écorce lisse et grise. Son odeur rappelle la sève de pin, en plus doux.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Guérit toutes les toux, mieux que l’herbe à chat.</dd></div><div><dt>L’utiliser</dt><dd>Avaler.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Tilia%20parvifolia%20%E2%80%94%20Flora%20Batava%20%E2%80%94%20Volume%20v18.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Tilleul</b><i class=\"lgdc-gbr__lat\">Tilia cordata</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Sous les hêtres, mêlé aux grands arbres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Grand arbre aux feuilles en cœur. Ses fleurs jaune pâle pendent sous une longue bractée et sentent le miel.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme l’angoisse et la colère, et aide à dormir.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les fleurs séchées.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Solidago%20virgaurea0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Verge d’or</b><i class=\"lgdc-gbr__lat\">Solidago virgaurea</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans la clairière</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petites fleurs jaune vif groupées en épis.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Aide les plaies à guérir.</dd></div><div><dt>L’utiliser</dt><dd>Appliquer en cataplasme.</dd></div></dl></div></li></ul></div><div class=\"lgdc-gbr__panel\" data-cat=\"orchidee\" style=\"--g1:#c2a24f\"><p class=\"lgdc-gbr__where\">Ce qui pousse sur les prairies de la lisière, le territoire du Clan de l’Orchidée.</p><ul class=\"lgdc-gbr__list\"><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Achillea%20millefolium%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-149.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Achillée mille-feuille</b><i class=\"lgdc-gbr__lat\">Achillea millefolium</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans les prairies</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleurs blanches en bouquets. Feuilles très fines et coupées.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Extraire le poison de l’organisme grâce au vomissement. Soigne les égratignures.</dd></div><div><dt>L’utiliser</dt><dd>Manger pour faire vomir ou appliquer comme cataplasme.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Crataegus%20oxyacantha%20%E2%80%94%20Flora%20Batava%20%E2%80%94%20Volume%20v5.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Aubépine</b><i class=\"lgdc-gbr__lat\">Crataegus laevigata</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les haies, contre les champs</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Arbuste épineux des haies, couvert de fleurs blanches à la saison des feuilles nouvelles, puis de petites baies rouges.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme le cœur qui s’affole et apaise l’angoisse.</dd></div><div><dt>L’utiliser</dt><dd>Manger quelques fleurs, ou quelques baies.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Arctium%20spp%20Sturm15.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Bardane</b><i class=\"lgdc-gbr__lat\">Arctium lappa</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, au bord des chemins</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Grande plante à fleurs violettes en boules accrocheuses, aux larges feuilles et à l’odeur forte. Sa racine a un goût amer.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Les feuilles soignent les démangeaisons et les inflammations. La racine guérit les infections des morsures de rat et en calme la douleur. Mangée, elle donne mal au ventre.</dd></div><div><dt>L’utiliser</dt><dd>Frotter la feuille contre la peau irritée. Déterrer la racine, la nettoyer et la mâcher en pâte pour un cataplasme.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Matricaria%20chamomilla0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Camomille</b><i class=\"lgdc-gbr__lat\">Matricaria chamomilla</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Au bord des champs</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleur aux pétales blancs et au centre jaune. Pousse en tas.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Diminue la fièvre, renforce le cœur et apaise l’esprit. Herbe fortifiante. Aide à lutter contre la fatigue et facilite la digestion.</dd></div><div><dt>L’utiliser</dt><dd>Manger.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Anthriscus%20sylvestris%20%28K%C3%B6hler%27s%20Medizinal-Pflanzen%29.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Cerfeuil</b><i class=\"lgdc-gbr__lat\">Anthriscus sylvestris</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Le long des haies</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante à l’odeur douce, aux larges feuilles ressemblant à des fougères et à petites fleurs blanches. Possède des racines marrons et tortueuses.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Le suc des feuilles désinfecte les plaies. Les racines apaisent les maux de ventre. Les feuilles apaisent aussi les maux de ventre mais elles sont moins puissantes que les racines.</dd></div><div><dt>L’utiliser</dt><dd>Appliquer la pulpe de la feuille sur la plaie ou la démangeaison. Mâcher la racine pour les maux de ventre.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Rosa%20canina0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Églantier</b><i class=\"lgdc-gbr__lat\">Rosa canina</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les haies, contre les champs</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Rosier sauvage épineux aux fleurs rose pâle. Ses fruits rouges mûrissent à la saison des feuilles mortes.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Redonne des forces pendant la mauvaise saison et aide à faire tomber la fièvre.</dd></div><div><dt>L’utiliser</dt><dd>Manger la chair des fruits, sans les poils de l’intérieur, qui grattent la gorge.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Papaver%20rhoeas%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-101.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Graines de pavot</b><i class=\"lgdc-gbr__lat\">Papaver rhoeas</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Au bord des champs</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Minuscules graines noires rondes récoltées en secouant une fleur de coquelicot séchée.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Elles peuvent aider un chat à dormir, calmer des chocs ou le stress, apaiser la douleur. Ne sont pas recommandées pour des reines allaitantes.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Conium%20maculatum%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-191.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Grande ciguë</b><i class=\"lgdc-gbr__lat\">Conium maculatum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Au bord du ruisseau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Haute plante aux petites fleurs blanches en ombrelles, à la tige tachée de pourpre. Odeur de souris.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Paralysie, puis mort.</dd></div><div><dt>L’utiliser</dt><dd>Aucun.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Convolvulus%20arvensis0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Liseron</b><i class=\"lgdc-gbr__lat\">Convolvulus arvensis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Au bord des champs</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante à fleurs blanches ou roses en entonnoir, qui s’enroule autour des autres plantes.</dd></div><div><dt>À quoi elle sert</dt><dd>Peut aider, avec des bâtons, à maintenir un membre en place lorsqu’il est cassé.</dd></div><div><dt>L’utiliser</dt><dd>Lier la tige autour d’un membre et de bâtons.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Malva%20sylvestris%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-222.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Mauve</b><i class=\"lgdc-gbr__lat\">Malva sylvestris</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, au bord des chemins</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleurs roses à mauves, veinées de pourpre. Grandes feuilles douces au toucher, odeur douce et agréable.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme la toux.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Mentha%20arvensis%20Lindman%20DESC.png?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Menthe</b><i class=\"lgdc-gbr__lat\">Mentha arvensis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Au bord du ruisseau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Feuilles douces et dentelées qui varient du vert au violet et au jaune. Les fleurs, quant à elles, sont plutôt petites et présentent des nuances de blanc ou de violet.</dd></div><div><dt>À quoi elle sert</dt><dd>Masque l’odeur de la mort.</dd></div><div><dt>L’utiliser</dt><dd>Frotter sur le corps d’un chat mort.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Billeder%20af%20nordens%20flora%20%28Plate%20230%29%20BHL10459661.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Millepertuis</b><i class=\"lgdc-gbr__lat\">Hypericum perforatum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Sur la colline</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleurs jaunes à cinq pétales ; les feuilles, vues à contre-jour, sont percées de petits points clairs.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soigne les brûlures et les plaies.</dd></div><div><dt>L’utiliser</dt><dd>Cataplasme de fleurs.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Billeder%20af%20nordens%20flora%20%281917%29%20%2819750123373%29.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Mouron des oiseaux</b><i class=\"lgdc-gbr__lat\">Stellaria media</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Au bord des champs</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petite plante étalée au sol, aux minuscules fleurs blanches en étoile.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Traite le mal vert, mais moins bien que l’herbe à chat.</dd></div><div><dt>L’utiliser</dt><dd>Manger, comme l’herbe à chat.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Nordens%20flora%20Rumex%20acetosa.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Oseille</b><i class=\"lgdc-gbr__lat\">Rumex acetosa</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans les prairies</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante haute avec des fleurs rouges et de grosses feuilles, en tas.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Le suc permet d’éviter les infections dues aux égratignures (pique à l’application). Herbe fortifiante (pour éviter les sensations de soif).</dd></div><div><dt>L’utiliser</dt><dd>Mâcher et appliquer sur la blessure. Manger.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Bellis%20perennis.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Pâquerette</b><i class=\"lgdc-gbr__lat\">Bellis perennis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les prairies</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleurs aux pétales blancs et au cœur jaune.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Fortifie l’organisme et augmente les forces. Assouplit les articulations. Herbe fortifiante.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles pour transformer en cataplasme. Manger (herbe fortifiante).</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Taraxacum%20officinale%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-135.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Pissenlit</b><i class=\"lgdc-gbr__lat\">Taraxacum officinale</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans les prairies</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fleur aux pétales jaunes et à la tige verte, creuse et pleine de lait.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Le lait de la tige soigne les piqûres d’abeille. Mâchée, la racine calme comme les graines de pavot. Aide aussi à tarir le lait d’une reine.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Plantago%20major0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Plantain</b><i class=\"lgdc-gbr__lat\">Plantago major</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, au bord des chemins</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Larges feuilles nervurées, plaquées au sol, épi de fleurs brunes.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme les piqûres et aide les petites plaies à se refermer.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles et les appliquer.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Caltha%20palustris0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Populage des marais</b><i class=\"lgdc-gbr__lat\">Caltha palustris</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Au bord du ruisseau</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Grosses fleurs jaune vif, comme des boutons d’or géants, sur des feuilles rondes et luisantes, les pieds dans l’eau.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Brûle la bouche, irrite le ventre et fait vomir.</dd></div><div><dt>L’utiliser</dt><dd>Aucun.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Senecio%20jacobaea.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Séneçon jacobée</b><i class=\"lgdc-gbr__lat\">Jacobaea vulgaris</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Sur la colline</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante à fleurs jaunes aux feuilles pennées.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Fortifie les chats. Mélangé à des baies de genièvre, soulage les douleurs des articulations. En manger trop donne mal au ventre.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher et appliquer en cataplasme. Manger.</dd></div></dl></div></li></ul></div><div class=\"lgdc-gbr__panel\" data-cat=\"brouillard\" style=\"--g1:#8a99a4\"><p class=\"lgdc-gbr__where\">Ce qui pousse sur les marais des vallons, le territoire du Clan du Brouillard.</p><ul class=\"lgdc-gbr__list\"><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Arum%20maculatum0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Arum tacheté</b><i class=\"lgdc-gbr__lat\">Arum maculatum</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--poisons\">Poisons</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, dans les sous-bois humides</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Feuilles en fer de lance, grappe de baies rouge vif en fin d’été.</dd></div><div><dt>Ce qu’elle cause</dt><dd>Brûle la bouche et la gorge, fait gonfler la langue.</dd></div><div><dt>L’utiliser</dt><dd>Aucun.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Symphytum%20officinale%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-268.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Consoude</b><i class=\"lgdc-gbr__lat\">Symphytum officinale</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Au bord de l’étang</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante aux larges feuilles, aux petites grappes de fleurs en clochette roses, mauves ou blanches, et aux grosses racines noires à l’extérieur, blanches à l’intérieur. Odeur acide.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Aide les os à se ressouder après une fracture. Apaise les plaies et la douleur d’une griffe tordue. La racine aide aussi les yeux et les blessures à guérir. Souvent utilisée pour les anciens.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles en pulpe et l’appliquer sur la blessure, ou en envelopper une patte. Broyer la racine pour un cataplasme, ou en faire couler le jus dans un œil blessé.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Nasturtium%20officinale0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Cresson de fontaine</b><i class=\"lgdc-gbr__lat\">Nasturtium officinale</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les sources</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante des sources et de l’eau claire, aux feuilles rondes et luisantes, au goût piquant, avec de petites fleurs blanches.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Redonne des forces et l’appétit à un chat affaibli.</dd></div><div><dt>L’utiliser</dt><dd>Manger les feuilles fraîches, cueillies dans l’eau qui coule.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Alnus%20glutinosa0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Écorce d’aulne</b><i class=\"lgdc-gbr__lat\">Alnus glutinosa</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Au bord de l’étang</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Écorce gris-brun, plus claire sur les jeunes aulnes.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soulage les maux de dents.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Salix%20alba0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Écorce de saule</b><i class=\"lgdc-gbr__lat\">Salix alba</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Au bord de l’étang</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Tronc rugueux et irrégulier.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Apaise la douleur.</dd></div><div><dt>L’utiliser</dt><dd>Avaler le suc.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Humulus%20lupulus0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Houblon</b><i class=\"lgdc-gbr__lat\">Humulus lupulus</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les fourrés humides, au bord de l’étang</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Liane grimpante des fourrés humides, aux feuilles rugueuses en forme de patte ouverte, avec des cônes vert pâle à l’odeur forte.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme la colère et la peur, et aide à dormir.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les cônes.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Juncus%20hostii0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Jonc</b><i class=\"lgdc-gbr__lat\">Juncus effusus</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Dans les roseaux</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante avec de longues tiges et des \"fleurs\" marron.</dd></div><div><dt>À quoi elle sert</dt><dd>Permet de lier des fractures.</dd></div><div><dt>L’utiliser</dt><dd>Utilisé comme attelle.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Mentha%20aquatica%20%E2%80%94%20Flora%20Batava%20%E2%80%94%20Volume%20v3.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Menthe aquatique</b><i class=\"lgdc-gbr__lat\">Mentha aquatica</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les roseaux</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petite plante aux feuilles vertes et rondes, et aux fleurs rose clair.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme les maux de ventre et chasse les vertiges.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher en pulpe.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Equisetum%20arvense%20Lindman%20DESC.jpeg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Prêle</b><i class=\"lgdc-gbr__lat\">Equisetum arvense</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans la boue, au bord de l’étang</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Haute plante verte à la tige piquante avec de grandes épines.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Permet de traiter les blessures infectées.</dd></div><div><dt>L’utiliser</dt><dd>Utilisée en cataplasme.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Filipendula%20ulmaria0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Reine-des-prés</b><i class=\"lgdc-gbr__lat\">Filipendula ulmaria</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les roseaux</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Haute plante aux bouquets mousseux de fleurs crème, au parfum de miel.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Fait baisser la fièvre et calme les douleurs.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les fleurs ou les feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Tanacetum%20vulgare0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Tanaisie</b><i class=\"lgdc-gbr__lat\">Tanacetum vulgare</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Aux frontières, sur les berges</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Plante à fleurs rondes et jaunes à l’odeur forte.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Utilisée pour guérir la toux.</dd></div><div><dt>L’utiliser</dt><dd>Mangeable (mais toxique et hallucinogène, mortelle à forte dose).</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Valeriana%20officinalis%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-143.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Valériane</b><i class=\"lgdc-gbr__lat\">Valeriana officinalis</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Dans les roseaux</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Grande tige aux fleurs roses en ombelle ; la racine sent fort, et les chats l’adorent.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme et aide à dormir. Trop en donner rend le chat agité.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher la racine.</dd></div></dl></div></li></ul></div><div class=\"lgdc-gbr__panel\" data-cat=\"partout\" style=\"--g1:#7d766d\"><p class=\"lgdc-gbr__where\">Ce qui pousse sur les quatre territoires.</p><ul class=\"lgdc-gbr__list\"><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Die%20S%C3%A4ugthiere%20in%20Abbildungen%20nach%20der%20Natur%2C%20mit%20Beschreibungen%20%28Plate%20CLXXXI%29%20%288610004476%29.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Bile de souris</b><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Dans chaque souris attrapée</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Liquide nauséabond et vert-jaune. Elle a un mauvais goût et aussi une très mauvaise odeur.</dd></div><div><dt>À quoi elle sert</dt><dd>Fait lâcher prise aux tiques. Sur une blessure, son goût empêche le blessé de la mordiller.</dd></div><div><dt>L’utiliser</dt><dd>Tamponner la tique avec un peu de mousse trempée dedans. Appliquer sur une blessure.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Glechoma%20hederacea0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Lierre terrestre</b><i class=\"lgdc-gbr__lat\">Glechoma hederacea</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--maladies\">Maladies</span></p><p class=\"lgdc-gbr__lieu\">Au pied des haies et des arbres</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Petite plante rampante aux feuilles rondes et crénelées, aux fleurs violettes, à l’odeur forte.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Calme la toux et dégage la poitrine.</dd></div><div><dt>L’utiliser</dt><dd>Mâcher les feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Polytrichum%20commune%20%E2%80%94%20Flora%20Batava%20%E2%80%94%20Volume%20v8.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Mousse</b><span class=\"lgdc-gbr__tag lgdc-gbr__tag--autres\">Autres usages</span></p><p class=\"lgdc-gbr__lieu\">Sur les troncs et les pierres humides</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Végétal spongieux, vert et doux, qu’on trouve partout sur les arbres et dans les endroits humides.</dd></div><div><dt>À quoi elle sert</dt><dd>Sert de litière, et transporte l’eau, le miel ou la bile de souris. Mouillée, elle s’appuie sur une plaie pour arrêter le saignement.</dd></div><div><dt>L’utiliser</dt><dd>Ramasser et garder au sec, ou tremper dans un liquide.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Urtica%20dioica0.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Ortie</b><i class=\"lgdc-gbr__lat\">Urtica dioica</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Près des camps</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Grande plante couverte de poils qui piquent, sur la tige et les feuilles. Graines vertes et piquantes.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Les graines font rejeter le poison, par exemple après avoir mangé de la chair à corbeau. Les feuilles font dégonfler les blessures enflées. Le cataplasme de tige aide les plaies à guérir. Frottées sur une patte raide, les feuilles la dégourdissent.</dd></div><div><dt>L’utiliser</dt><dd>Manger les graines pour faire vomir, comme avec l’achillée. Manger les feuilles, ou les appliquer en cataplasme avec la tige.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Rumex%20obtusifolius%20Sturm48.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Patience</b><i class=\"lgdc-gbr__lat\">Rumex obtusifolius</i><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Près des camps</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Grandes feuilles vertes.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Soulage les irritations.</dd></div><div><dt>L’utiliser</dt><dd>Frotter contre les coussinets.</dd></div></dl></div></li><li class=\"lgdc-gbr__item\"><div class=\"lgdc-gbr__thumb\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Kruisspin%20in%20zijn%20web%2C%20RP-P-1921-1932.jpg?width=140\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__body\"><p class=\"lgdc-gbr__top\"><b>Toiles d’araignée</b><span class=\"lgdc-gbr__tag lgdc-gbr__tag--blessures\">Blessures</span></p><p class=\"lgdc-gbr__lieu\">Dans les buissons et au fond des tanières</p><dl class=\"lgdc-gbr__facts\"><div><dt>L’identifier</dt><dd>Fils blancs et collants que l’araignée tisse avec son abdomen.</dd></div><div><dt>Ce qu’elle guérit</dt><dd>Permet d’arrêter une hémorragie, d’absorber le sang d’une blessure pour la garder propre, de faire tenir un cataplasme ou de bander des membres fracturés.</dd></div><div><dt>L’utiliser</dt><dd>Enrouler autour d’une blessure (attention à ne pas ramasser l’araignée avec).</dd></div></dl></div></li></ul></div></div>\n          </div>\n          <p class=\"lgdc-gbr__credit\">Planches botaniques du domaine public (Köhler, Thomé, Lindman, Sturm…), via Wikimedia Commons.</p>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"glossaire\">\n        <section id=\"glossaire\">\n          <h2>Glossaire</h2>\n          <p>Les chats des Clans ont leurs propres mots. Ce glossaire vient du wiki de <i>La Guerre des Clans</i>, sans les lieux et les Clans propres aux livres.</p><nav class=\"lgdc-gbg__index\" aria-label=\"Rubriques du glossaire\"><a href=\"#gl-rangs\">Les rangs</a><a href=\"#gl-camp\">Le camp</a><a href=\"#gl-vie\">La vie du Clan</a><a href=\"#gl-dehors\">Hors des Clans</a><a href=\"#gl-maladies\">Les maladies</a><a href=\"#gl-temps\">Le temps</a><a href=\"#gl-mesures\">Les mesures</a><a href=\"#gl-jurons\">Insultes et jurons</a><a href=\"#gl-expressions\">Expressions</a><a href=\"#gl-proverbes\">Proverbes</a></nav>\n        </section>\n\n        <section id=\"gl-rangs\">\n          <h2>Les rangs</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Chef</dt><dd>Chat qui dirige tout le Clan. Il reçoit neuf vies du Clan des Étoiles et prend un nom en « Étoile ».</dd></div><div><dt>Lieutenant</dt><dd>Guerrier qui seconde le chef, organise les patrouilles et le remplace à sa mort ou à sa retraite.</dd></div><div><dt>Guérisseur</dt><dd>Chat qui soigne les blessures et les maladies grâce aux plantes, et reçoit parfois des signes ou des prophéties du Clan des Étoiles.</dd></div><div><dt>Guerrier</dt><dd>Chat adulte qui a terminé sa formation. Une chatte reste guerrière tant qu’elle n’attend pas ou n’allaite pas de petits.</dd></div><div><dt>Mentor</dt><dd>Guerrier qui forme un apprenti.</dd></div><div><dt>Apprenti</dt><dd>Chat d’au moins six lunes qui apprend le métier de guerrier, ou parfois celui de guérisseur.</dd></div><div><dt>Reine</dt><dd>Chatte qui attend ou élève des petits, ou qui reste à la pouponnière pour aider les autres reines.</dd></div><div><dt>Chaton</dt><dd>Chat de moins de six lunes.</dd></div><div><dt>Ancien</dt><dd>Chat d’au moins 85 lunes, ou plus jeune s’il ne peut plus chasser ni se battre. Très respecté : les apprentis lui apportent à manger, lui retirent ses puces et changent sa litière.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-camp\">\n          <h2>Le camp</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Camp</dt><dd>Lieu de vie principal du Clan.</dd></div><div><dt>Tanière du chef</dt><dd>Tanière qui appartient au chef.</dd></div><div><dt>Tanière du guérisseur</dt><dd>Tanière où vivent le guérisseur et son apprenti, et où l’on soigne les malades.</dd></div><div><dt>Tanière des guerriers</dt><dd>Tanière des guerriers et du lieutenant.</dd></div><div><dt>Tanière des apprentis</dt><dd>Tanière des apprentis.</dd></div><div><dt>Tanière des anciens</dt><dd>Tanière des anciens.</dd></div><div><dt>Pouponnière</dt><dd>Tanière partagée par les reines et leurs chatons.</dd></div><div><dt>Pile de gibier</dt><dd>Endroit, souvent au centre du camp, où les chasseurs déposent leurs proies pour tout le Clan.</dd></div><div><dt>Petit coin</dt><dd>Endroit près du camp où les chats font leurs besoins.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-vie\">\n          <h2>La vie du Clan</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Assemblée</dt><dd>Réunion des quatre Clans à chaque pleine lune, pendant une trêve voulue par le Clan des Étoiles.</dd></div><div><dt>Clan des Étoiles</dt><dd>Les ancêtres morts des Clans, qui veillent sur eux depuis le ciel.</dd></div><div><dt>Toison Argentée</dt><dd>La Voie lactée. Chaque étoile est un chat du Clan des Étoiles.</dd></div><div><dt>Camarade de Clan</dt><dd>Chat du même Clan.</dd></div><div><dt>Patrouille de chasse</dt><dd>Groupe de chats qui chassent pour nourrir le Clan, et qui peuvent repousser les intrus.</dd></div><div><dt>Proie fraîche</dt><dd>Proie tout juste tuée pour être mangée. Les anciens, les chatons, les reines et les malades mangent en premier, puis les guerriers et les apprentis.</dd></div><div><dt>Le partage</dt><dd>Deux chats se toilettent l’un l’autre en échangeant les dernières nouvelles.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-dehors\">\n          <h2>Hors des Clans</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Solitaire</dt><dd>Chat qui vit seul et ne défend pas de territoire.</dd></div><div><dt>Chat errant</dt><dd>Chat souvent hostile, seul ou en bande, sans Bipèdes ni territoire, qui ignore les frontières des Clans.</dd></div><div><dt>Chat domestique</dt><dd>Chat qui vit chez les Bipèdes, souvent avec un collier, et toujours bien nourri.</dd></div><div><dt>Bipède</dt><dd>Humain. Certains solitaires disent aussi « Sans-Fourrure » ou « Deux-Pattes ».</dd></div><div><dt>Petit Bipède</dt><dd>Enfant.</dd></div><div><dt>Maisonnier</dt><dd>Bipède qui possède un chat domestique.</dd></div><div><dt>Coupeur</dt><dd>Vétérinaire.</dd></div><div><dt>Nid de Bipèdes</dt><dd>Maison.</dd></div><div><dt>Territoire des Bipèdes</dt><dd>Village ou ville.</dd></div><div><dt>Chemin du Tonnerre</dt><dd>Route.</dd></div><div><dt>Monstre</dt><dd>Véhicule des Bipèdes.</dd></div><div><dt>Dévoreur d’arbre</dt><dd>Engin de bûcheron.</dd></div><div><dt>Ronce argentée</dt><dd>Fil barbelé.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-maladies\">\n          <h2>Les maladies</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Mal blanc</dt><dd>Maladie contagieuse, surtout chez les chatons et les anciens, qui peut vite tourner au mal vert.</dd></div><div><dt>Mal vert</dt><dd>Maladie contagieuse, souvent mortelle.</dd></div><div><dt>Mal jaune</dt><dd>Maladie qui s’attaque aux poumons, soignée par la pulmonaire.</dd></div><div><dt>Mal noir</dt><dd>Infection de la poitrine.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-temps\">\n          <h2>Le temps</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Saison des feuilles nouvelles</dt><dd>Le printemps.</dd></div><div><dt>Saison des feuilles vertes</dt><dd>L’été.</dd></div><div><dt>Saison des feuilles mortes</dt><dd>L’automne.</dd></div><div><dt>Mauvaise saison</dt><dd>L’hiver.</dd></div><div><dt>Saison</dt><dd>Un quart d’année.</dd></div><div><dt>Lune</dt><dd>Un mois.</dd></div><div><dt>Demi-lune</dt><dd>Deux semaines.</dd></div><div><dt>Quart de lune</dt><dd>Une semaine.</dd></div><div><dt>Battement de cœur</dt><dd>Quelques secondes.</dd></div><div><dt>Aube</dt><dd>Le moment qui précède le lever du soleil.</dd></div><div><dt>Lever du soleil</dt><dd>L’aurore.</dd></div><div><dt>Midi</dt><dd>Le soleil au plus haut.</dd></div><div><dt>Coucher du soleil</dt><dd>Le crépuscule du soir.</dd></div><div><dt>Crépuscule</dt><dd>Le lever de la lune.</dd></div><div><dt>Minuit</dt><dd>La lune au plus haut.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-mesures\">\n          <h2>Les mesures</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Longueur de souris</dt><dd>Environ 5 à 7 cm.</dd></div><div><dt>Longueur de queue</dt><dd>Environ 30 cm.</dd></div><div><dt>Bond de lapin</dt><dd>Environ 45 cm.</dd></div><div><dt>Longueur de renard</dt><dd>Environ 80 cm.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-jurons\">\n          <h2>Insultes et jurons</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Cervelle de souris</dt><dd>Imbécile. Peut être amical. Variantes : cervelle de lièvre, d’oiseau, de lapin, de puce, d’abeille.</dd></div><div><dt>Boule de poils, cerveau mou</dt><dd>Insultes amicales mais sévères : tout dépend du ton.</dd></div><div><dt>Cœur de renard</dt><dd>Cruel, sans cœur.</dd></div><div><dt>Cœur de souris</dt><dd>Lâche.</dd></div><div><dt>Souris effrayée !</dt><dd>Chat qui a peur de tout.</dd></div><div><dt>Haleine de renard</dt><dd>Chat qui a mauvaise haleine.</dd></div><div><dt>Loir</dt><dd>Chat qui dort beaucoup.</dd></div><div><dt>Face de crotte</dt><dd>Insulte grave et ancienne.</dd></div><div><dt>Peau galeuse</dt><dd>Insulte.</dd></div><div><dt>Patte propre</dt><dd>Chat qui s’en tient strictement aux règles (méprisant).</dd></div><div><dt>Chauve-souris aveugle</dt><dd>Se moque de la vue d’un chat.</dd></div><div><dt>Crotte de souris !</dt><dd>Juron de dégoût ou de déception. Variantes : crotte de lièvre, crotte de renard.</dd></div><div><dt>Par le Clan des Étoiles !</dt><dd>Surprise ou colère extrême. Aussi : « Au nom du Clan des Étoiles ! »</dd></div><div><dt>Dans toutes les étoiles !</dt><dd>Exaspération.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-expressions\">\n          <h2>Expressions</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Chair à corbeau</dt><dd>Nourriture pourrie ou répugnante. Aussi une insulte.</dd></div><div><dt>Qui a ébouriffé sa fourrure ?</dt><dd>Se dit de ce qui agace quelqu’un.</dd></div><div><dt>Aussi utile qu’un renard mort</dt><dd>Totalement inutile.</dd></div><div><dt>Des abeilles te bourdonnent dans le crâne !</dt><dd>Tu dis n’importe quoi.</dd></div><div><dt>Plus fou qu’un renard en crise !</dt><dd>Se dit d’un chat qui agit sans raison.</dd></div><div><dt>Peu importe une moustache</dt><dd>Ça m’est égal. Ou : la patrouille n’a rien attrapé.</dd></div><div><dt>Je n’en donnerais pas une queue de souris</dt><dd>Je m’en moque.</dd></div><div><dt>Comme le Clan du Lion</dt><dd>Avec une férocité ou un courage immenses. Aussi : « comme le Clan du Tigre ».</dd></div><div><dt>Quand les hérissons voleront</dt><dd>Jamais.</dd></div><div><dt>Il fait aussi sombre qu’un cœur de renard</dt><dd>Il fait noir comme dans un four.</dd></div><div><dt>Tu chasses comme un chat domestique !</dt><dd>Moquerie envers un chat qui chasse ou se bat mal.</dd></div><div><dt>Tu aurais fait de la viande de souris !</dt><dd>Je t’aurais mis en lambeaux.</dd></div><div><dt>Seul le Clan des Étoiles le sait</dt><dd>Réponse à une question sans réponse.</dd></div><div><dt>Que le Clan des Étoiles éclaire ton chemin</dt><dd>Bonne chance.</dd></div><div><dt>Bonne chasse, course rapide, et un abri quand tu dors</dt><dd>Très ancien adieu, commun à tous les Clans.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-proverbes\">\n          <h2>Proverbes</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Mieux vaut effrayer une souris qu’accueillir un blaireau</dt><dd>Mieux vaut faire fuir un ami que laisser entrer un ennemi.</dd></div><div><dt>Chat domestique un jour, chat domestique toujours</dt><dd>Insulte envers un chat d’origine domestique.</dd></div><div><dt>Les excuses, ça ne nourrit pas son chat</dt><dd>S’excuser ne change pas le passé.</dd></div><div><dt>Un chat tigré ne quitte pas ses rayures</dt><dd>On ne change pas sa nature.</dd></div></dl>\n          <p class=\"lgdc-gbg__credit\">Adapté du <a href=\"https://lgdc.fandom.com/fr/wiki/Glossaire\">glossaire du Wiki La Guerre des Clans</a> et de ses contributeurs, sous licence CC BY-SA. Définitions abrégées ; lieux et Clans propres aux livres omis.</p>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"credits\">\n        <section id=\"cr-merci\">\n          <h2>Un merci particulier</h2><div class=\"lgdc-thanks\" data-mark=\"merci\"><p class=\"lgdc-thanks__name\">Pandaries</p><p class=\"lgdc-thanks__txt\">Un immense bravo pour son travail sur <a href=\"https://themistrials.forumactif.com/\">Themis Trials</a>. La modification du profil directement sur la page, notamment, s’inspire de ses codes : ils ont complètement changé mon idée de ce qu’un forum Forumactif peut offrir en confort d’utilisation. Merci à elle. Longue vie à Themis Trials !</p></div>\n        </section>\n\n        <section id=\"cr-saga\">\n          <h2>La saga</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt><i>La Guerre des Clans</i></dt><dd>Erin Hunter, éditions Pocket Jeunesse pour la traduction française. Wildheart est un forum de fans, sans lien avec les éditeurs. Le code du guerrier est repris de la traduction officielle.</dd></div><div><dt>Wiki <i>La Guerre des Clans</i></dt><dd><a href=\"https://lgdc.fandom.com/fr/\">lgdc.fandom.com</a>, licence CC BY-SA. Base des remèdes, du glossaire et de la banque du générateur de noms.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-systeme\">\n          <h2>Le système</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt><i>Warriors Adventure Game</i></dt><dd>Working Partners. Le jeu de rôle officiel de la saga, dont s’inspirent les gestes, la chasse et les capacités de Clan.</dd></div><div><dt><i>Fabula Ultima</i></dt><dd>Need Games. Source des attributs en taille de dé, des liens et des altérations.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-reserve\">\n          <h2>La réserve</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt>Parc national de forêts</dt><dd>Le plan de gestion de la réserve intégrale d’Arc-Châteauvillain a servi à vérifier les plantes, les animaux et les noms présents dans la réserve.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-images\">\n          <h2>Les images</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt>Illustrations de chats</dt><dd>Les dessins de chats du forum sont de <a href=\"https://www.tumblr.com/greyratdog\">greyratdog</a>.</dd></div><div><dt>Smileys</dt><dd>Les smileys de chats orange sont de l’artiste <a href=\"https://vgen.co/Seviyummy\">Seviyummy</a>, pack <i>Orange Cats</i>.</dd></div><div><dt>Pleine lune de la bannière</dt><dd>Gregory H. Revera, Wikimedia Commons (« FullMoon2010.jpg »), licence CC BY-SA 3.0.</dd></div><div><dt>Photographies</dt><dd><a href=\"https://unsplash.com/\">Unsplash</a>, licence Unsplash : la brume et la forêt d’automne.</dd></div><div><dt>Planches des remèdes</dt><dd>Domaine public, via Wikimedia Commons : Köhler, <i>Medizinal-Pflanzen</i> (1887) ; Thomé, <i>Flora von Deutschland</i> (1885) ; Sturm, <i>Deutschlands Flora</i> ; Lindman, <i>Bilder ur Nordens Flora</i> ; <i>Flora Batava</i> ; Lindley, <i>Collectanea botanica</i> (1821) ; Schreber, <i>Die Säugthiere</i> ; estampes du Rijksmuseum d’Amsterdam.</dd></div><div><dt>Symboles des Clans</dt><dd>Créations originales pour Wildheart.</dd></div><div><dt>Carte de la réserve</dt><dd>Dessinée avec <a href=\"https://inkarnate.com/\">Inkarnate</a>.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-code\">\n          <h2>Le code du forum</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt>Truesight</dt><dd>This skin uses the tooltip system <b>\"Truesight\"</b> (<a href=\"https://necodemancer.github.io/schoolofnecromancy/truesight/\">Usage guide</a>) made by <a href=\"https://necromancercoding.tumblr.com/\">Necromancer Coding</a>.</dd></div><div><dt>Notiffi</dt><dd>Plugin de notifications de Kim.</dd></div><div><dt>Switcheroo</dt><dd>Panneau de changement de personnage de Poumon (Monomer).</dd></div><div><dt>GSAP</dt><dd>Animation de la bannière, par GreenSock (licence standard gratuite).</dd></div><div><dt>Lancer de dés</dt><dd>Algorithmes publics cyrb53 et mulberry32, de bryc (domaine public).</dd></div><div><dt>Inspiration</dt><dd>Le design s’inspire du forum <a href=\"https://ourepitaph.jcink.net/\">Our Epitaph</a> et du pen « epitaph » de pharaohleap, sur CodePen.</dd></div><div><dt>Polices et icônes</dt><dd>Playfair Display et Google Sans (Google Fonts, licence OFL), Obviously (Adobe Fonts), icônes Phosphor (licence MIT).</dd></div></dl>\n        </section>\n\n      </div>\n\n    </div>\n  </article>\n</div>\n\n</main>";
  mount.replaceWith(fragment.content);
})();

/* Les chapitres, sous-onglets et rubriques restent accessibles par leur adresse. */
(function () {
  function open() {
    var h = location.hash.slice(1), r = document.getElementById('lgdc-gb-' + h), c = document.getElementById('lgdc-gbc-' + h);
    var m = h.indexOf('remedes-') === 0 ? document.getElementById('lgdc-gbr-' + h.slice(8)) : null;
    var section = document.getElementById(h);
    if (c) { c.checked = true; r = document.getElementById('lgdc-gb-clans'); }
    if (m) { m.checked = true; r = document.getElementById('lgdc-gb-remedes'); }
    if (!r && section) {
      var panel = section.closest('.lgdc-gb__panel');
      if (panel) r = document.getElementById('lgdc-gb-' + panel.dataset.tab);
    }
    var sub = section ? section.closest('[data-radio]') : null;
    if (sub) document.getElementById(sub.dataset.radio).checked = true;
    if (r) r.checked = true;
    if (r && section) section.scrollIntoView();
  }
  open(); window.addEventListener('hashchange', open);
  document.querySelector('.lgdc-gb').addEventListener('change', function (e) {
    if (e.target.type !== 'radio') return;
    var id = e.target.id.replace(/^lgdc-gbc?-/, '');
    if (e.target.name === 'lgdc-gbr') id = e.target.id.replace('lgdc-gbr-', 'remedes-');
    if (e.target.name === 'lgdc-gbsy') id = e.target.id.replace('lgdc-gbsy-', 'sys-');
    if (id === 'clans') { var c = document.querySelector('[name="lgdc-gbc"]:checked'); if (c && c !== document.querySelector('[name="lgdc-gbc"]')) id = c.id.slice(9); }
    history.replaceState(null, '', '#' + id);
  });
})();
